CREATE FUNCTION auth.bootstrap_person(p_email text, p_name text, p_roles public.global_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare person uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('heed.dev_people', 0));
  insert into people(email, display_name) values(p_email,p_name) on conflict(email) do nothing;
  select id into person from people where email=p_email and deactivated_at is null and erased_at is null;
  if person is null then return; end if;
  insert into auth.dev_people(person_id) values(person) on conflict do nothing;
  if found then
    insert into global_role_grants(person_id,role)
      select person, r from unnest(p_roles) r
      where not exists(select 1 from global_role_grants g where g.person_id=person and g.role=r and g.valid_at @> now());
  end if;
end $$;

CREATE FUNCTION public.area_deletions_guard_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.restored_at is not null
     or (to_jsonb(new) - 'restored_by' - 'restored_at' - 'restored_edition')
        <> (to_jsonb(old) - 'restored_by' - 'restored_at' - 'restored_edition') then
    raise exception 'a domain deletion may only be restored, once' using errcode = 'restrict_violation'; end if;
  return new;
end $$;

CREATE FUNCTION public.audit_chain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
declare prev bytea;
begin
  perform pg_advisory_xact_lock(hashtextextended('context_layer.audit', 0));
  new.seq := nextval(pg_get_serial_sequence('audit_log', 'seq'));
  select hash into prev from audit_log order by seq desc limit 1;
  new.prev_hash := prev;
  new.hash := sha256(coalesce(prev, '\x'::bytea) || convert_to(concat_ws('|', new.at, new.actor_id, new.actor_kind, new.action, new.area_id,
                new.subject_type, new.subject_id, new.request_id, new.details::text,
                case when coalesce(new.batch_id::text, new.reason, new.source) is not null
                     then jsonb_build_object('batch', new.batch_id, 'reason', new.reason, 'source', new.source)::text end), 'UTF8'));
  return new;
end $$;

CREATE FUNCTION public.audit_verify() RETURNS TABLE(first_bad_seq bigint)
    LANGUAGE sql STABLE
    SET "TimeZone" TO 'UTC'
    AS $$
  select a.seq from (select *, lag(hash) over (order by seq) as expect_prev from audit_log) a
   where a.prev_hash is distinct from a.expect_prev
      or a.hash <> sha256(coalesce(a.prev_hash, '\x'::bytea) || convert_to(concat_ws('|', a.at, a.actor_id, a.actor_kind, a.action, a.area_id,
                a.subject_type, a.subject_id, a.request_id, a.details::text,
                case when coalesce(a.batch_id::text, a.reason, a.source) is not null
                     then jsonb_build_object('batch', a.batch_id, 'reason', a.reason, 'source', a.source)::text end), 'UTF8'))
   order by a.seq limit 1 $$;

CREATE FUNCTION public.cl_area_delete(p_area text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare held record;
begin
  if not cl_is_admin_now() then
    raise exception 'only an administrator deletes a domain' using errcode = 'insufficient_privilege';
  end if;
  if exists (select 1 from areas where id = p_area and is_demo) then
    raise exception 'the demo domain always exists' using errcode = 'check_violation';
  end if;
  select * into held from cl_area_holdings(p_area);
  if held.items + held.terms + held.open_proposals + held.source_members + held.drafts > 0 or held.history then
    raise exception 'domain % holds context or history; archive it instead', p_area using errcode = 'foreign_key_violation';
  end if;
  delete from area_assignments where area_id = p_area;
  delete from areas where id = p_area;
  if not found then raise exception 'no domain %', p_area using errcode = 'no_data_found'; end if;
end $$;

CREATE FUNCTION public.cl_area_deletion_plan(p_area text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_live bigint := (select seq from live_edition); v_plan jsonb;
begin
  if not cl_is_admin_now() then
    raise exception 'only an administrator reads what deleting a domain does' using errcode = 'insufficient_privilege';
  end if;
  with live_terms as (
    select s.term_key as key, s.version_id, t.kind, t.parent_key, v.name, v.area_id
      from vocab_term_service s join vocab_term_versions v on v.id = s.version_id
      join vocab_terms t on t.key = s.term_key
     where s.editions @> v_live),
  other_items as (
    select v.id from item_version_service s join item_versions v on v.id = s.version_id
     where s.editions @> v_live and v.area_id <> p_area),
  used as (
    select m.metric_key as key from item_version_metrics m join other_items o on o.id = m.version_id
    union select d.dimension_key from item_version_dimension_values d join other_items o on o.id = d.version_id
    union select d.value_key from item_version_dimension_values d join other_items o on o.id = d.version_id
    union select d.dimension_key from item_version_dimensions d join other_items o on o.id = d.version_id)
  select jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.item_id, 'versionId', v.id,
                                          'title', case when cl_audience_allows(v.audience_groups) then v.title end,
                                          'withheld', not cl_audience_allows(v.audience_groups), 'kind', i.kind,
                                          'proposerId', v.proposer_id)
                       order by not cl_audience_allows(v.audience_groups), v.title, s.item_id)
        from item_version_service s join item_versions v on v.id = s.version_id join items i on i.id = s.item_id
       where s.editions @> v_live and v.area_id = p_area), '[]'::jsonb),
    'terms', coalesce((
      select jsonb_agg(jsonb_build_object('key', t.key, 'versionId', t.version_id, 'name', t.name, 'kind', t.kind,
                                          'parentKey', t.parent_key,
                                          'usedElsewhere', exists (select 1 from used u where u.key = t.key))
                       order by t.name, t.key)
        from live_terms t where t.area_id = p_area), '[]'::jsonb),
    'parentsOfOthers', coalesce((
      select jsonb_agg(distinct t.parent_key) from live_terms t
       where t.parent_key is not null and t.area_id is distinct from p_area), '[]'::jsonb),
    'sourceTerms', coalesce((
      select jsonb_agg(jsonb_build_object('key', t.key, 'name', t.name, 'kind', t.kind) order by t.name, t.key)
        from live_terms t join source_domain_service d on d.term_key = t.key and d.editions @> v_live
       where t.area_id is null and d.area_id = p_area), '[]'::jsonb),
    'openProposals', coalesce((
      select jsonb_agg(jsonb_build_object('id', p.id, 'number', p.number, 'subject', p.subject, 'revision', p.revision,
                                          'proposerId', p.proposer_id,
                                          'title', case when o.open
                                                   then coalesce(iv.title, tv.name, p.draft->>'title', p.draft->>'name', 'Untitled') end,
                                          'withheld', not o.open)
                       order by not o.open, p.number)
        from proposals p left join item_versions iv on iv.id = p.item_version_id
        left join vocab_term_versions tv on tv.id = p.vocab_version_id
        cross join lateral (select cl_item_open(p.item_id) and cl_version_open(p.item_version_id) as open) o
       where p.area_id = p_area and p.discarded_at is null and p.state in ('submitted', 'in_review', 'changes_requested')),
      '[]'::jsonb),
    'drafts', coalesce((
      select jsonb_agg(jsonb_build_object('id', p.id, 'proposerId', p.proposer_id, 'author', a.display_name,
                                          'title', coalesce(nullif(btrim(p.draft->>'title'), ''), 'Untitled draft'))
                       order by p.created_at, p.id)
        from proposals p join people a on a.id = p.proposer_id
       where p.area_id = p_area and p.discarded_at is null and p.state = 'draft'), '[]'::jsonb),
    'team', coalesce((
      select jsonb_agg(jsonb_build_object('personId', x.person_id, 'name', a.display_name, 'role', x.role)
                       order by x.role, a.display_name, x.person_id)
        from area_assignments x join people a on a.id = x.person_id
       where x.area_id = p_area and x.valid_at @> now()), '[]'::jsonb),
    'sourceMembers', (select count(*) from definitions where area_hint = p_area and missing_since_snapshot is null),
    'history', (select h.history from cl_area_holdings(p_area) h))
  into v_plan;
  return v_plan;
end $$;

CREATE FUNCTION public.cl_area_holdings(p_area text) RETURNS TABLE(items integer, terms integer, open_proposals integer, source_members integer, drafts integer, team integer, history boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare ref record; named boolean;
begin
  if not cl_is_admin_now() then
    raise exception 'only an administrator reads what a domain holds' using errcode = 'insufficient_privilege';
  end if;
  items := (select count(*) from item_version_service s join item_versions v on v.id = s.version_id
             where s.editions @> (select seq from live_edition) and v.area_id = p_area);
  terms := (select count(*) from (
               select s.term_key from vocab_term_service s join vocab_term_versions v on v.id = s.version_id
                where s.editions @> (select seq from live_edition) and v.area_id = p_area
               union
               select term_key from source_domain_service
                where editions @> (select seq from live_edition) and area_id = p_area) t);
  open_proposals := (select count(*) from proposals where area_id = p_area and discarded_at is null
                      and state in ('submitted', 'in_review', 'changes_requested'));
  source_members := (select count(*) from definitions where area_hint = p_area and missing_since_snapshot is null);
  drafts := (select count(*) from proposals where area_id = p_area and discarded_at is null and state = 'draft');
  team := (select count(*) from area_assignments where area_id = p_area and valid_at @> now());
  history := false;
  for ref in
    select c.conrelid::regclass as tbl, a.attname as col
      from pg_constraint c join pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
     where c.contype = 'f' and c.confrelid = 'areas'::regclass and c.conrelid <> 'area_assignments'::regclass
  loop
    execute format('select exists (select 1 from %s where %I = $1)', ref.tbl, ref.col) into named using p_area;
    if named then history := true; exit; end if;
  end loop;
  return next;
end $_$;

CREATE FUNCTION public.cl_area_review_times(p_area text, p_since timestamp with time zone) RETURNS TABLE(decided integer, median_hours double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*)::int, percentile_cont(0.5) within group (order by extract(epoch from x.decided_at - x.submitted_at) / 3600)
    from (select p.id, p.submitted_at, min(d.decided_at) as decided_at
            from decisions d join proposals p on p.id = d.proposal_id
           where d.area_id = p_area and p.submitted_at is not null
           group by p.id, p.submitted_at) x
   where x.decided_at >= p_since and x.decided_at >= x.submitted_at
$$;

CREATE FUNCTION public.cl_audience_allows(p_audience text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ select p_audience is null $$;

CREATE FUNCTION public.cl_count_delivery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.caller = 'agent' and new.topic_id is not null then
    insert into topic_week_counts (topic_id, week, status, calls, no_item_calls)
    values (new.topic_id, date_trunc('week', new.delivered_hour at time zone 'UTC')::date, new.status, 1,
            case when jsonb_array_length(new.delivered) = 0 then 1 else 0 end)
    on conflict (topic_id, week, status) do update
      set calls = topic_week_counts.calls + 1,
          no_item_calls = topic_week_counts.no_item_calls + excluded.no_item_calls;
  end if;
  return null;
end $$;

CREATE FUNCTION public.cl_decides_own(p_person uuid, p_area text, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$ select cl_is_admin(p_person, p_at) or (p_area is not null and cl_has_area_role(p_person, p_area, 'owner', p_at)) $$;

CREATE FUNCTION public.cl_edition_versions(p_seq bigint) RETURNS TABLE(item_id text, version_id uuid, digest text, open boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.item_id, s.version_id, encode(v.content_digest, 'hex'), cl_version_open(v.id)
    from item_version_service s join item_versions v on v.id = s.version_id
   where s.editions @> p_seq $$;

CREATE FUNCTION public.cl_ensure_delivery_partitions(p_months_ahead integer DEFAULT 2) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare m date; n int := 0; part text;
begin
  if p_months_ahead is null or p_months_ahead not between 0 and 12 then
    raise exception 'months ahead must be between 0 and 12' using errcode = '22023';
  end if;
  for i in 0 .. p_months_ahead loop
    m := (date_trunc('month', now() at time zone 'UTC') + make_interval(months => i))::date;
    part := 'deliveries_' || to_char(m, 'YYYY_MM');
    if to_regclass(part) is null then
      execute format('create table %I partition of deliveries for values from (%L) to (%L)', part, m::timestamp at time zone 'UTC', (m + interval '1 month')::timestamp at time zone 'UTC');
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;

CREATE FUNCTION public.cl_ensure_request_partitions(p_months_ahead integer DEFAULT 2) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare m date; n int := 0; part text;
begin
  if p_months_ahead is null or p_months_ahead not between 0 and 12 then
    raise exception 'months ahead must be between 0 and 12' using errcode = '22023';
  end if;
  for i in 0 .. p_months_ahead loop
    m := (date_trunc('month', now() at time zone 'UTC') + make_interval(months => i))::date;
    part := 'mcp_requests_' || to_char(m, 'YYYY_MM');
    if to_regclass(part) is null then
      execute format('create table %I partition of mcp_requests for values from (%L) to (%L)', part, m::timestamp at time zone 'UTC', (m + interval '1 month')::timestamp at time zone 'UTC');
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;

CREATE FUNCTION public.cl_eval_versions_due() RETURNS TABLE(version_id uuid, proposer_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select v.id, v.proposer_id from proposals p join item_versions v on v.id = p.item_version_id
   where p.subject = 'item' and p.action in ('create', 'change', 'recheck') and p.state in ('submitted', 'in_review')
     and v.risk in ('normal', 'high') and v.audience_groups is null
     and exists (select 1 from live_edition)
     and not exists (select 1 from eval_runs r where r.item_version_id = v.id
                       and r.baseline_edition_seq = (select seq from live_edition))
   order by p.submitted_at, v.id limit 50 $$;

CREATE FUNCTION public.cl_feedback_area() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.area_id is null and new.delivery_id is not null then
    select t.area_id into new.area_id
      from deliveries d join topics t on t.id = d.topic_id
     where d.id = new.delivery_id
     limit 1;
  end if;
  return new;
end $$;

CREATE FUNCTION public.cl_forbid_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception '% on % is not allowed (append-only)', tg_op, tg_table_name
    using errcode = 'restrict_violation';
end $$;

CREATE FUNCTION public.cl_gap_draft_tests(p_proposal uuid) RETURNS SETOF text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into proposal_tests (proposal_id, question_id)
  select p.id, x.question_id
    from proposals p
    join gap_tests x on x.gap_id = p.source_gap_id
    join golden_questions q on q.id = x.question_id
   where p.id = p_proposal and p.proposer_id = cl_person() and p.state = 'draft' and p.discarded_at is null
     and q.split = 'development' and q.status = 'active' and q.area_id = p.area_id
   order by x.question_id
  on conflict do nothing
  returning question_id
$$;

CREATE FUNCTION public.cl_gap_history(p_gap uuid) RETURNS TABLE(action text, hour timestamp with time zone, details jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select a.action, date_trunc('hour', a.at, 'UTC'), a.details
    from gaps g join topics t on t.id = g.topic_id
    join audit_log a on a.subject_type = 'gap' and a.subject_id = g.ref
   where g.id = p_gap and cl_manages_topic(t.area_id, t.metric_keys)
   order by a.seq
$$;

CREATE FUNCTION public.cl_gap_record_pass(p_run uuid, p_gap uuid, p_question text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_hour timestamptz;
begin
  update gap_tests x
     set passed_run = r.id,
         passed_edition_seq = r.baseline_edition_seq,
         passed_revision = (select (p->>'revision')::int from jsonb_array_elements(r.summary->'plan'->'questions') p
                             where p->>'id' = x.question_id limit 1),
         passed_hour = date_trunc('hour', r.finished_at, 'UTC')
    from eval_runs r, gaps g, topics t
   where r.id = p_run and x.gap_id = p_gap and x.question_id = p_question and x.passed_run is null
     and g.id = x.gap_id and t.id = g.topic_id and r.area_id = any(cl_topic_domains(t.area_id, t.metric_keys))
     and r.state = 'finished' and r.kind in ('scheduled', 'full') and r.proposal_id is null and r.item_version_id is null
     and g.status = 'resolved' and r.baseline_edition_seq >= g.resolved_edition_seq
     and exists (select 1 from jsonb_array_elements(r.summary->'result'->'questions') v
                  where v->>'id' = x.question_id and v->>'baseline' = 'pass')
  returning x.passed_hour into v_hour;
  return v_hour;
end $$;

CREATE FUNCTION public.cl_gap_run_tests(p_run uuid) RETURNS TABLE(gap uuid, ref text, resolved_seq bigint, verified boolean, question text, active boolean, passed_seq bigint, passed_hour timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select g.id, g.ref, g.resolved_edition_seq, g.verified_at is not null, x.question_id, q.status = 'active',
         x.passed_edition_seq, x.passed_hour
    from eval_runs r
    join topics t on r.area_id = any(cl_topic_domains(t.area_id, t.metric_keys))
    join gaps g on g.topic_id = t.id
    join gap_tests x on x.gap_id = g.id
    join golden_questions q on q.id = x.question_id
   where r.id = p_run and r.state = 'finished' and r.kind in ('scheduled', 'full')
     and r.proposal_id is null and r.item_version_id is null
     and g.status = 'resolved' and g.resolved_edition_seq is not null
   order by g.id, x.question_id
     for no key update of g
$$;

CREATE FUNCTION public.cl_gap_touch(p_topic uuid, p_type public.gap_type, p_case smallint, p_seen timestamp with time zone, p_first timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reports integer DEFAULT 0, p_note text DEFAULT NULL::text, p_note_source text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  g gaps%rowtype;
  v_last date := (p_seen at time zone 'UTC')::date;
  v_first date := (coalesce(p_first, p_seen) at time zone 'UTC')::date;
begin
  perform pg_advisory_xact_lock(hashtextextended('cl.gap:' || p_topic || ':' || p_type, 0));
  select * into g from gaps where topic_id = p_topic and type = p_type
   order by status in ('open', 'proposal_made') desc, status = 'wont_fix' desc, status_since desc, created_at desc
   limit 1;
  if not found or (g.status = 'resolved' and p_seen > g.status_since) then
    insert into gaps (topic_id, type, opened_by_case, first_seen, last_seen)
    values (p_topic, p_type, p_case, v_first, v_last) returning * into g;
  elsif g.status = 'resolved' then
    return g.id;
  else
    update gaps set last_seen = greatest(last_seen, v_last) where id = g.id;
  end if;
  if p_reports > 0 then
    insert into gap_weekly_counts (gap_id, week, reports)
    values (g.id, date_trunc('week', p_seen at time zone 'UTC')::date, p_reports)
    on conflict (gap_id, week) do update set reports = gap_weekly_counts.reports + excluded.reports;
  end if;
  if p_note is not null then
    insert into gap_notes (gap_id, source, note) values (g.id, p_note_source, p_note);
  end if;
  return g.id;
end $$;

CREATE FUNCTION public.cl_gaps_detect() RETURNS TABLE(what text, n bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_rule jsonb := (select value from settings_current where key = 'gaps.no_item_threshold');
  v_calls int := (v_rule ->> 'calls')::int;
  v_days int := (v_rule ->> 'days')::int;
  v_kept int := (select (value #>> '{}')::int from settings_current where key = 'retention.delivery_days');
  r record; k bigint; g uuid;
begin
  if v_calls is null or v_days is null or v_kept is null or least(v_calls, v_days, v_kept) < 1 then
    raise exception 'gaps.no_item_threshold and retention.delivery_days must be set and at least one' using errcode = '22023';
  end if;

  -- Case 1: enough agent calls about one topic found nothing within the period. A check failure
  -- is not a gap (FR-319), and calls from before a resolution do not count again.
  k := 0;
  for r in
    select d.topic_id, min(d.delivered_hour) as first_hour, max(d.delivered_hour) as last_hour
      from deliveries d
     where d.caller = 'agent' and d.status = 'no_match' and d.topic_id is not null
       and d.delivered_hour >= date_trunc('hour', now(), 'UTC') - make_interval(days => v_days)
       and d.delivered_hour > coalesce((select max(x.status_since) from gaps x
             where x.topic_id = d.topic_id and x.type = 'missing' and x.status = 'resolved'), '-infinity')
     group by d.topic_id
    having count(*) >= v_calls
  loop
    perform cl_gap_touch(r.topic_id, 'missing', 1::smallint, r.last_hour, r.first_hour);
    k := k + 1;
  end loop;
  return query select 'case_1_no_item_topics', k;

  -- Case 3: negative feedback on an agent delivery. Its note moves under the notes' row security.
  -- Feedback older than the kept deliveries can no longer find its topic.
  k := 0;
  for r in
    select f.id, f.verdict, f.note, f.created_hour, d.topic_id
      from feedback f join deliveries d on d.id = f.delivery_id
     where f.gap_id is null and f.verdict <> 'helpful' and d.caller = 'agent' and d.topic_id is not null
       and f.created_hour >= now() - make_interval(days => v_kept)
     order by f.created_hour, f.id
  loop
    g := cl_gap_touch(r.topic_id,
           case r.verdict when 'wrong' then 'incorrect' when 'missing' then 'missing' else 'unclear_question' end::gap_type,
           3::smallint, r.created_hour, null, 1, r.note, 'feedback');
    update feedback set gap_id = g, note = null where id = r.id;
    k := k + 1;
  end loop;
  return query select 'case_3_feedback', k;

  -- Case 4: a source definition changed (not a first sighting or a reappearance with the same
  -- mark). Recent topics about a metric defined there may now hold outdated context.
  k := 0;
  for r in
    select distinct t.id as topic_id, s.fetched_at
      from definition_marks m
      join connector_snapshots s on s.id = m.snapshot_id
      join lateral (select p.change_mark from definition_marks p join connector_snapshots ps on ps.id = p.snapshot_id
                     where p.definition_ref = m.definition_ref and ps.fetched_at < s.fetched_at
                     order by ps.fetched_at desc limit 1) prev on prev.change_mark <> m.change_mark
      join vocab_term_refs tr on tr.definition_ref = m.definition_ref
      join vocab_term_versions v on v.id = tr.version_id
      join topics t on v.term_key = any(t.metric_keys)
                   and t.month >= (date_trunc('month', s.fetched_at at time zone 'UTC') - interval '1 month')::date
     where s.fetched_at >= now() - make_interval(days => v_days)
  loop
    perform cl_gap_touch(r.topic_id, 'outdated', 4::smallint, r.fetched_at);
    k := k + 1;
  end loop;
  return query select 'case_4_definition_topics', k;

  -- Weekly no-item calls of every gap still in play, from the topic's counts since it was seen.
  insert into gap_weekly_counts (gap_id, week, no_item_calls)
  select x.id, c.week, sum(c.no_item_calls)
    from gaps x join topic_week_counts c on c.topic_id = x.topic_id and c.status = 'no_match'
   where x.type = 'missing' and x.status in ('open', 'proposal_made', 'wont_fix')
     and c.week >= date_trunc('week', x.first_seen)::date
   group by x.id, c.week
  having sum(c.no_item_calls) > 0
  on conflict (gap_id, week) do update set no_item_calls = excluded.no_item_calls
   where gap_weekly_counts.no_item_calls is distinct from excluded.no_item_calls;
  get diagnostics k = row_count;
  return query select 'weekly_counts_updated', k;
end $$;

CREATE FUNCTION public.cl_has_area_role(p_person uuid, p_area text, p_role public.area_role, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$ select exists (select 1 from area_assignments a where a.person_id = p_person and a.area_id = p_area and a.role = p_role and a.valid_at @> p_at) $$;

CREATE FUNCTION public.cl_person() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$ select nullif(current_setting('cl.person_id', true), '')::uuid $$;

CREATE TABLE public.outbox_events (
    seq bigint NOT NULL,
    id uuid DEFAULT uuidv7() NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    topic text NOT NULL,
    area_id text,
    aggregate_type text NOT NULL,
    aggregate_id text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    relayed_at timestamp with time zone,
    actor_id uuid DEFAULT public.cl_person(),
    relay_seq bigint,
    CONSTRAINT outbox_events_topic_check CHECK ((topic ~ '^[a-z_]+\.[a-z_]+$'::text)),
    CONSTRAINT outbox_relayed_together CHECK (((relay_seq IS NULL) = (relayed_at IS NULL)))
);

CREATE FUNCTION public.cl_inbox_recipients(e public.outbox_events) RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p proposals; reviewers uuid[]; owners uuid[]; discussing uuid[];
begin
  if e.topic = 'area.deleted' then
    return query
      select distinct r from area_deletions d cross join unnest(d.recipients) r join people x on x.id = r
       where d.id = (e.payload->>'deletion')::uuid
         and x.deactivated_at is null and x.erased_at is null and r is distinct from e.actor_id;
    return;
  end if;
  if e.topic in ('item.flagged', 'item.links_stale', 'vocabulary.domain_changed', 'gap.verified') then
    owners := case when e.area_id is null then array(
        select g.person_id from global_role_grants g where g.role = 'administrator' and g.valid_at @> now())
      else array(
        select a.person_id from area_assignments a
         where a.area_id = e.area_id and a.role = 'owner' and a.valid_at @> now()) end;
    return query
      select distinct r from unnest(owners) r join people x on x.id = r
       where x.deactivated_at is null and x.erased_at is null and r is distinct from e.actor_id;
    return;
  end if;
  if e.aggregate_type <> 'proposal' then return; end if;
  select * into p from proposals where id = e.aggregate_id::uuid;
  if not found then return; end if;
  reviewers := case when p.claimed_by is not null then array[p.claimed_by] else array(
    select a.person_id from area_assignments a
     where a.area_id = p.area_id and a.role = 'owner' and a.valid_at @> now()) end;
  discussing := case when p.claimed_by is null and p.area_id is null and p.subject = 'vocabulary' then array(
    select g.person_id from global_role_grants g where g.role = 'administrator' and g.valid_at @> now())
    else reviewers end;
  return query
    select distinct r from unnest(case e.topic
        when 'proposal.submitted'   then reviewers
        when 'proposal.commented'   then array[p.proposer_id] || discussing
        when 'proposal.claimed'     then array[p.proposer_id]
        when 'proposal.handed_over' then array[(e.payload->>'personId')::uuid]
        when 'proposal.withdrawn'   then reviewers
        when 'proposal.decided'     then array[p.proposer_id]
        else '{}'::uuid[] end) r
      join people x on x.id = r
     where x.deactivated_at is null and x.erased_at is null and r is distinct from e.actor_id;
end $$;

CREATE FUNCTION public.cl_is_admin(p_person uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$ select exists (select 1 from global_role_grants g where g.person_id = p_person and g.role = 'administrator' and g.valid_at @> p_at) $$;

CREATE FUNCTION public.cl_is_admin_now() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select cl_person() is not null and cl_is_admin(cl_person(), now()) $$;

CREATE FUNCTION public.cl_is_auditor_now() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select cl_person() is not null and exists (select 1 from global_role_grants g where g.person_id = cl_person() and g.role in ('auditor','administrator') and g.valid_at @> now()) $$;

CREATE FUNCTION public.cl_is_owner_now(p_area text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select cl_person() is not null and cl_has_area_role(cl_person(), p_area, 'owner', now()) $$;

CREATE FUNCTION public.cl_is_reviewer_now(p_area text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select cl_person() is not null and (cl_has_area_role(cl_person(), p_area, 'owner', now())
       or cl_has_area_role(cl_person(), p_area, 'approver', now())) $$;

CREATE FUNCTION public.cl_item_open(p_item text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select cl_audience_allows(v.audience_groups)
                     from item_version_service s join item_versions v on v.id = s.version_id
                    where s.item_id = p_item order by lower(s.editions) desc limit 1), true) $$;

CREATE FUNCTION public.cl_item_version_kept(p_version uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  select jsonb_build_object(
    'item', v.item_id, 'title', v.title, 'summary', v.summary, 'body', v.body,
    'summaryMarkup', v.summary_markup, 'bodyMarkup', v.body_markup, 'notToConclude', v.not_to_conclude,
    'validFrom', v.valid_from, 'validUntil', v.valid_until, 'proposer', v.proposer_id, 'via', v.created_via,
    'audience', v.audience_groups, 'recheck', v.is_recheck,
    'metrics', (select coalesce(jsonb_agg(m.metric_key order by m.metric_key), '[]')
                  from item_version_metrics m where m.version_id = v.id),
    'dimensions', (select coalesce(jsonb_agg(d.dimension_key order by d.dimension_key), '[]')
                     from item_version_dimensions d where d.version_id = v.id),
    'values', (select coalesce(jsonb_agg(jsonb_build_array(d.dimension_key, d.value_key) order by d.value_key), '[]')
                 from item_version_dimension_values d where d.version_id = v.id),
    'evidence', (select coalesce(jsonb_agg(jsonb_build_array(e.url, e.quote, e.read_on) order by e.position), '[]')
                   from item_version_evidence e where e.version_id = v.id),
    'references', (select coalesce(jsonb_object_agg(r.definition_ref, r.change_mark), '{}')
                     from item_version_refs r where r.version_id = v.id),
    'replaces', (select coalesce(jsonb_agg(x.replaced_item_id order by x.replaced_item_id), '[]')
                   from item_version_replaces x where x.version_id = v.id),
    'conflicts', (select coalesce(jsonb_agg(c.other_item_id order by c.other_item_id), '[]')
                    from item_version_conflicts c where c.version_id = v.id),
    'mentions', (select coalesce(jsonb_agg(jsonb_build_array(n.field, n.position, n.label, n.term_key, n.item_id, n.area_id)
                                           order by n.field, n.position), '[]')
                   from item_version_mentions n where n.version_id = v.id))
  from item_versions v where v.id = p_version $$;

CREATE FUNCTION public.cl_item_version_problem(p_version uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
declare v item_versions; prev item_versions; owner_ok boolean; approver_ok boolean; waive boolean := false;
begin
  select * into v from item_versions where id = p_version;
  if not found then return 'version does not exist'; end if;
  if v.is_recheck then                       -- CON-211: only change marks / review date may differ
    select * into prev from item_versions where id = v.supersedes_version_id;
    if not found or prev.core_digest <> v.core_digest then return 'a recheck must keep the content of the version it checks'; end if;
    waive := true;
  end if;
  select exists (select 1 from decisions d
    where d.item_version_id = v.id and d.outcome = 'accept' and d.area_id = v.area_id
      and ((d.capacity in ('owner', 'deputy') and cl_has_area_role(d.decided_by, v.area_id, 'owner', d.decided_at))
        or (d.capacity = 'administrator' and cl_is_admin(d.decided_by, d.decided_at)))
      and (waive or v.risk = 'low' or d.decided_by <> v.proposer_id
           or cl_decides_own(d.decided_by, v.area_id, d.decided_at))) into owner_ok;          -- FR-202, FR-206
  if not owner_ok then return 'no accept decision by an owner of the domain or an administrator'; end if;
  if v.risk = 'high' then                                                                           -- FR-207
    select exists (select 1 from decisions d
      where d.item_version_id = v.id and d.outcome = 'accept' and d.capacity = 'approver'
        and cl_has_area_role(d.decided_by, v.area_id, 'approver', d.decided_at)
        and (d.decided_by <> v.proposer_id or cl_decides_own(d.decided_by, v.area_id, d.decided_at))) into approver_ok;
    if not approver_ok then return 'high risk needs an accept decision by a named approver'; end if;
  end if;
  if not cl_version_gate_ok(v.id) then return 'a required check has not passed'; end if;          -- FR-205
  return null;
end $$;

CREATE FUNCTION public.cl_live_term_refs(p_key text) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(r.definition_ref order by r.definition_ref collate "C"), '{}')
    from vocab_term_service s join vocab_term_refs r on r.version_id = s.version_id
   where s.term_key = p_key and s.editions @> (select seq from live_edition) $$;

CREATE FUNCTION public.cl_make_append_only(tbl regclass) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare base text := replace(tbl::text, '.', '_');
begin
  execute format('create trigger %I before update or delete on %s for each row execute function cl_forbid_mutation()', 'ao_row_' || base, tbl);
  execute format('create trigger %I before truncate on %s for each statement execute function cl_forbid_mutation()', 'ao_trunc_' || base, tbl);
end $$;

CREATE FUNCTION public.cl_manages_topic(p_area text, p_metrics text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select cl_is_admin_now() or exists (select 1 from unnest(cl_topic_domains(p_area, p_metrics)) a where cl_is_owner_now(a)) $$;

CREATE FUNCTION public.cl_mention_mark() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.term_key is null then return new; end if;
  select d.ref, d.change_mark into new.definition_ref, new.change_mark
    from unnest(cl_relevant_refs(cl_live_term_refs(new.term_key), cl_version_metric_refs(new.version_id)))
           with ordinality x(ref, n)
    join definitions d on d.ref = x.ref
   order by x.n limit 1;
  return new;
end $$;

CREATE FUNCTION public.cl_next_item_version(p_item text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if cl_person() is null then raise exception 'Sign in required' using errcode='insufficient_privilege'; end if;
  perform 1 from items where id=p_item for update;
  return (select coalesce(max(version_no),0)+1 from item_versions where item_id=p_item);
end $$;

CREATE FUNCTION public.cl_other_proposal_overlap(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists(select 1 from proposals mine join proposals other on other.id<>mine.id
    where mine.id=p_id and (mine.proposer_id=cl_person() or cl_is_admin_now() or cl_is_owner_now(mine.area_id))
      and other.proposer_id<>cl_person() and other.state in ('draft','submitted','in_review','changes_requested')
      and other.discarded_at is null and cl_scopes_overlap(mine.draft,other.draft)) $$;

CREATE FUNCTION public.cl_outbox_relay(p_limit integer DEFAULT 200) RETURNS TABLE(relayed integer, delivered integer, head bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare e outbox_events; v_relayed int := 0; v_delivered int := 0; v_head bigint; k int;
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'relay batch must be 1 to 1000 events' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('context_layer.outbox_relay', 0));
  for e in select * from outbox_events where relayed_at is null order by seq limit p_limit for update loop
    insert into inbox_items (person_id, event_seq, kind, area_id, subject_type, subject_id, actor_id, payload)
    select r, e.seq, e.topic, e.area_id, e.aggregate_type, e.aggregate_id, e.actor_id, e.payload
      from cl_inbox_recipients(e) r
    on conflict (person_id, event_seq) do nothing;
    get diagnostics k = row_count;
    v_delivered := v_delivered + k;
    update outbox_events set relayed_at = now(), relay_seq = nextval('outbox_relay_seq')
     where seq = e.seq returning relay_seq into v_head;
    v_relayed := v_relayed + 1;
  end loop;
  if v_relayed > 0 then perform pg_notify('cl_relayed', v_head::text); end if;
  return query select v_relayed, v_delivered, v_head;
end $$;

CREATE FUNCTION public.cl_parse_mention_text(t text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare i int := 1; rest text; m text[]; plain text := ''; tokens jsonb := '[]';
begin
  while i <= char_length(t) loop
    if substr(t,i,1) = chr(92) and substr(t,i+1,1) in (chr(92),'@') then
      plain := plain || substr(t,i+1,1); i := i+2;
    elsif substr(t,i,2) = '@[' then
      rest := substr(t,i);
      m := regexp_match(rest, '^@\[([^\]\r\n]+)\]\(((?:metric|dim):[a-z0-9_]+|val:[a-z0-9_]+/[a-z0-9_]+|item:itm_[a-z0-9]{8,16}|area:[a-z][a-z0-9_-]*)\)');
      if m is null then raise exception 'Invalid mention syntax' using errcode='check_violation'; end if;
      plain := plain || m[1];
      tokens := tokens || jsonb_build_array(jsonb_build_object('position',jsonb_array_length(tokens),'label',m[1],'target',m[2]));
      i := i + char_length(m[1]) + char_length(m[2]) + 5;
    else plain := plain || substr(t,i,1); i := i+1;
    end if;
  end loop;
  return jsonb_build_object('text',plain,'mentions',tokens);
end $$;

CREATE FUNCTION public.cl_proposal_tests_follow_area() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  with gone as (
    delete from proposal_tests a using golden_questions q
     where a.proposal_id = new.id and q.id = a.question_id and q.area_id is distinct from new.area_id
    returning a.question_id)
  insert into audit_log (actor_id, actor_kind, action, area_id, subject_type, subject_id, details)
  select cl_person(), case when cl_person() is null then 'system' else 'person' end, 'proposal.test_detached',
         old.area_id, 'proposal', new.id::text,
         jsonb_build_object('question', question_id, 'reason', 'area_changed')
    from gone order by question_id;
  return null;
end $$;

CREATE FUNCTION public.cl_question_links_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  attached boolean := exists (
    select 1 from proposal_tests a join proposals p on p.id = a.proposal_id
     where a.question_id = new.id and p.discarded_at is null
       and p.state in ('draft', 'submitted', 'in_review', 'changes_requested'));
begin
  if new.split = 'held_out' and old.split <> 'held_out' and attached then
    raise exception 'The test question % is attached to an open proposal; detach it before holding it out', new.id
      using errcode = '23514';
  end if;
  if new.area_id <> old.area_id and (attached or exists (select 1 from gap_tests where question_id = new.id)) then
    raise exception 'The test question % is linked to a gap or attached to an open proposal; remove those before moving it', new.id
      using errcode = '23514';
  end if;
  return new;
end $$;

CREATE FUNCTION public.cl_ref_view(p_ref text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when strpos(m, '.') > 0 and length(m) - strpos(reverse(m), '.') > 0
              then left(m, length(m) - strpos(reverse(m), '.')) end
    from (select substr(p_ref, strpos(p_ref, ':') + 1) as m) x $$;

CREATE FUNCTION public.cl_relevant_refs(p_refs text[], p_metric_refs text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when cardinality(p_refs) < 2 then p_refs
              else coalesce(nullif(array(
                     select r from unnest(p_refs) with ordinality u(r, n)
                      where cl_ref_view(r) in (select cl_ref_view(x) from unnest(p_metric_refs) x)
                      order by n), '{}'), p_refs) end $$;

CREATE FUNCTION public.cl_report_gap_person(p_key text, p_area text, p_metrics text[], p_values text[], p_dimensions text[], p_month date, p_type public.gap_type, p_note text, p_retry bytea, p_request bytea) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  topic uuid;
  g uuid;
  prior gap_report_keys%rowtype;
begin
  if p_note is not null and char_length(p_note) not between 1 and 500 then
    raise exception 'A note has 1 to 500 characters' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('cl.gap_report:' || encode(p_retry, 'hex'), 0));
  delete from gap_report_keys where expires_hour <= now();
  select * into prior from gap_report_keys where retry_digest = p_retry;
  if found then
    if prior.request_digest <> p_request then
      raise exception 'This retry key was used for a different report' using errcode = '22023';
    end if;
    return prior.gap_id;
  end if;
  insert into topics (key, area_id, metric_keys, value_keys, dimension_keys, month)
    values (p_key, p_area, p_metrics, p_values, coalesce(p_dimensions, '{}'), p_month)
    on conflict (key) do nothing;
  select id into topic from topics where key = p_key;
  g := cl_gap_touch(topic, p_type, 5::smallint, now(), null, 1, p_note, 'person');
  -- cl_gap_touch counted the report in this week's row; this marks it as a person's.
  update gap_weekly_counts set human_reports = human_reports + 1
   where gap_id = g and week = date_trunc('week', now() at time zone 'UTC')::date;
  insert into gap_report_keys (retry_digest, request_digest, gap_id) values (p_retry, p_request, g);
  return g;
end $$;

CREATE FUNCTION public.cl_required_levels(r public.risk_level) RETURNS public.check_level[]
    LANGUAGE sql IMMUTABLE
    AS $$
  select case r when 'low'    then array['format','matching','delivery']::check_level[]
                when 'normal' then array['format','matching','delivery','answer_impact']::check_level[]
                else               array['format','matching','delivery','answer_impact','answer_full']::check_level[] end $$;

CREATE FUNCTION public.cl_retention_run() RETURNS TABLE(what text, n bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_delivery int := (select (value #>> '{}')::int from settings_current where key = 'retention.delivery_days');
  v_requests int := (select (value #>> '{}')::int from settings_current where key = 'retention.request_log_days');
  v_outbox   int := (select (value #>> '{}')::int from settings_current where key = 'retention.outbox_days');
  v_notes    int := (select (value #>> '{}')::int from settings_current where key = 'retention.note_days');
  part record; cutoff timestamptz; dropped bigint := 0; k bigint;
begin
  if v_delivery is null or v_requests is null or v_outbox is null or v_notes is null
     or least(v_delivery, v_requests, v_outbox, v_notes) < 1 then
    raise exception 'retention periods must be set and at least one day' using errcode = '22023';
  end if;
  delete from gap_notes where created_hour < now() - make_interval(days => v_notes);                get diagnostics k = row_count; return query select 'gap_notes', k;
  update feedback set note = null where note is not null and created_hour < now() - make_interval(days => v_notes); get diagnostics k = row_count; return query select 'feedback_notes', k;
  delete from idempotency_keys where expires_at < now();                 get diagnostics k = row_count; return query select 'idempotency_keys', k;
  delete from llm_spend_daily where expires_at < now();                  get diagnostics k = row_count; return query select 'llm_spend_daily', k;
  delete from inbox_items where archived_at < now() - interval '90 days'; get diagnostics k = row_count; return query select 'inbox_items', k;
  delete from outbox_events where relayed_at < now() - make_interval(days => v_outbox); get diagnostics k = row_count; return query select 'outbox_events', k;
  for part in select c.relname, p.relname as parent, pg_get_expr(c.relpartbound, c.oid) as bound
                from pg_inherits i join pg_class c on c.oid = i.inhrelid join pg_class p on p.oid = i.inhparent
               where p.relname in ('deliveries', 'mcp_requests') and p.relnamespace = 'public'::regnamespace loop
    cutoff := (regexp_match(part.bound, 'TO \(''([^'']+)''\)'))[1]::timestamptz;      -- upper bound of the partition
    if cutoff < now() - make_interval(days => case part.parent when 'deliveries' then v_delivery else v_requests end) then
      execute format('alter table %I detach partition %I', part.parent, part.relname);
      execute format('drop table %I', part.relname); dropped := dropped + 1;
    end if;
  end loop;
  return query select 'partitions_dropped', dropped;
end $$;

CREATE FUNCTION public.cl_scopes_overlap(a jsonb, b jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    (jsonb_array_length(coalesce(a->'scope'->'metrics','[]')) + jsonb_array_length(coalesce(a->'scope'->'dimensionValues','[]'))
       + jsonb_array_length(coalesce(a->'scope'->'dimensions','[]')) > 0) and
    (jsonb_array_length(coalesce(b->'scope'->'metrics','[]')) + jsonb_array_length(coalesce(b->'scope'->'dimensionValues','[]'))
       + jsonb_array_length(coalesce(b->'scope'->'dimensions','[]')) > 0) and
    (a->'validity'->>'start') < coalesce(b->'validity'->>'end','9999-12-31') and
    (b->'validity'->>'start') < coalesce(a->'validity'->>'end','9999-12-31') and
    (jsonb_array_length(coalesce(a->'scope'->'metrics','[]'))=0 or
     jsonb_array_length(coalesce(b->'scope'->'metrics','[]'))=0 or exists (
       select 1 from jsonb_array_elements_text(a->'scope'->'metrics') x,
                     jsonb_array_elements_text(b->'scope'->'metrics') y
       where x=y or exists (select 1 from vocab_terms t join vocab_term_service s on s.term_key=t.key
         where s.editions @> (select seq from live_edition)
           and ((t.key=x and t.parent_key=y) or (t.key=y and t.parent_key=x))))) and
    not exists (
      select 1 from jsonb_array_elements(coalesce(a->'scope'->'dimensionValues','[]')) x
      where exists(select 1 from jsonb_array_elements(coalesce(b->'scope'->'dimensionValues','[]')) y
                   where y->>'dimension'=x->>'dimension')
        and not exists(select 1 from jsonb_array_elements(coalesce(a->'scope'->'dimensionValues','[]')) ax,
                                     jsonb_array_elements(coalesce(b->'scope'->'dimensionValues','[]')) by_
                       where ax->>'dimension'=x->>'dimension' and by_->>'dimension'=x->>'dimension' and ax->>'value'=by_->>'value')) $$;

CREATE FUNCTION public.cl_service_edition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare boundary bigint;
begin
  perform edition_lock();
  if tg_op = 'INSERT' then
    boundary := lower(new.editions);
    if not upper_inf(new.editions) then
      raise exception 'service must start open-ended' using errcode = 'check_violation';
    end if;
  else
    boundary := upper(new.editions);
    if (to_jsonb(new) - 'editions') is distinct from (to_jsonb(old) - 'editions')
       or not upper_inf(old.editions) or upper_inf(new.editions)
       or lower(new.editions) <> lower(old.editions) or boundary <= lower(old.editions) then
      raise exception 'service rows may only be closed' using errcode = 'restrict_violation';
    end if;
  end if;
  if not exists (select 1 from editions where seq = boundary and sealed_at is null)
     or exists (select 1 from editions where seq >= boundary and sealed_at is not null) then
    raise exception 'service boundary must be an unsealed edition after sealed history' using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

CREATE FUNCTION public.cl_short_id(prefix text) RETURNS text
    LANGUAGE sql PARALLEL SAFE
    AS $$ select prefix || '_' || substr(replace(gen_random_uuid()::text, '-', ''), 20, 10) $$;

CREATE FUNCTION public.cl_similar_items(p_title text, p_summary text) RETURNS TABLE(item_id text, score real)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select v.item_id, greatest(similarity(v.title, coalesce(p_title, '')), similarity(v.summary, coalesce(p_summary, '')))
    from serving_items((select seq from live_edition)) v
   where v.audience_groups is null
     and greatest(similarity(v.title, coalesce(p_title, '')), similarity(v.summary, coalesce(p_summary, ''))) >= 0.3
   order by 2 desc, 1
   limit 20
$$;

CREATE FUNCTION public.cl_source_domains_behind() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with live as (select seq from live_edition),
  want as (select w.term_key, w.area_id from live, cl_source_domains_now(live.seq) w),
  have as (select d.term_key, d.area_id from live, source_domain_service d where d.editions @> live.seq)
  select exists (select 1 from live)
     and (exists (select * from want except select * from have) or exists (select * from have except select * from want)) $$;

CREATE FUNCTION public.cl_source_domains_now(p_seq bigint) RETURNS TABLE(term_key text, area_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.term_key, min(a.id)
    from vocab_term_service s
    join vocab_term_refs r on r.version_id = s.version_id
    join definitions d on d.ref = r.definition_ref
    left join areas a on a.id = d.area_hint and a.archived_at is null
   where s.editions @> p_seq
   group by s.term_key
  having count(distinct d.area_hint) = 1 and bool_and(a.id is not null) $$;

CREATE FUNCTION public.cl_strip_mentions(t text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select cl_parse_mention_text(t)->>'text' $$;

CREATE FUNCTION public.cl_test_link_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  q golden_questions%rowtype;
  v_ok boolean;
begin
  select * into strict q from golden_questions where id = new.question_id for share;
  if tg_table_name = 'gap_tests' then
    select q.area_id = any(cl_topic_domains(t.area_id, t.metric_keys)) into v_ok
      from gaps g join topics t on t.id = g.topic_id where g.id = new.gap_id;
  else
    if q.split = 'held_out' then
      raise exception 'A held-out test question cannot be attached to a proposal' using errcode = '23514';
    end if;
    select area_id is not distinct from q.area_id into v_ok from proposals where id = new.proposal_id;
  end if;
  if not coalesce(v_ok, false) then
    raise exception 'The test question % is not in the area of this %', q.id,
      case tg_table_name when 'gap_tests' then 'gap' else 'proposal' end using errcode = '23514';
  end if;
  return null;
end $$;

CREATE FUNCTION public.cl_topic_counts_public(p_min integer DEFAULT 5) RETURNS TABLE(topic_id uuid, week date, calls bigint, no_item_calls bigint)
    LANGUAGE sql STABLE
    AS $$
  select c.topic_id, c.week, sum(c.calls), sum(c.no_item_calls)
    from topic_week_counts c group by c.topic_id, c.week having sum(c.calls) >= p_min $$;

CREATE FUNCTION public.cl_topic_domains(p_area text, p_metrics text[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with live as (select seq from live_edition),
  domains as (
    select coalesce(v.area_id, d.area_id) as area_id
      from live join vocab_term_service s on s.editions @> live.seq
      join vocab_term_versions v on v.id = s.version_id
      left join source_domain_service d on d.term_key = s.term_key and d.editions @> live.seq
     where s.term_key = any(p_metrics))
  select case when p_area is not null then array[p_area]
              else coalesce((select array_agg(distinct area_id order by area_id) from domains where area_id is not null), '{}') end $$;

CREATE FUNCTION public.cl_topics_adopt_domains() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n int;
begin
  with found as (
    select t.id, t.key, cl_topic_domains(null, t.metric_keys) as domains from topics t where t.area_id is null),
  one as (select f.id, f.domains[1] || f.key as key, f.domains[1] as area_id from found f
           where cardinality(f.domains) = 1 and f.key like '|%')
  update topics t set area_id = o.area_id, key = o.key
    from one o where t.id = o.id and not exists (select 1 from topics x where x.key = o.key);
  get diagnostics n = row_count;
  return n;
end $$;

CREATE FUNCTION public.cl_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  return new;
end $$;

CREATE FUNCTION public.cl_version_child_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from item_versions where id = new.version_id
      and created_xact = pg_current_xact_id()) then
    raise exception 'version children must be inserted in the transaction that creates their version' using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

CREATE FUNCTION public.cl_version_gate_ok(p_version uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select not exists (
    select 1 from item_versions v cross join unnest(cl_required_levels(v.risk)) as need(level)
    where v.id = p_version
      and coalesce((select r.outcome from check_results r where r.item_version_id = v.id and r.level = need.level
                    order by r.ran_at desc, r.id desc limit 1), 'failed') <> 'passed') $$;

CREATE FUNCTION public.cl_version_metric_refs(p_version uuid) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(r.definition_ref order by r.definition_ref collate "C"), '{}')
    from item_version_metrics m
    join vocab_term_service s on s.term_key = m.metric_key and s.editions @> (select seq from live_edition)
    join vocab_term_refs r on r.version_id = s.version_id
   where m.version_id = p_version $$;

CREATE FUNCTION public.cl_version_open(p_version uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select cl_audience_allows(v.audience_groups) and cl_item_open(v.item_id)
                     from item_versions v where v.id = p_version), true) $$;

CREATE FUNCTION public.cl_version_review(p_version uuid) RETURNS TABLE(accepted_on date, accepted_as public.decision_capacity, accepted_area text, accepted_by uuid, first_edition text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select (d.decided_at at time zone 'UTC')::date, d.capacity, d.area_id, d.decided_by, f.label
    from (select 1) one
    left join lateral (select x.decided_at, x.capacity, x.area_id, x.decided_by from decisions x
       where x.item_version_id = p_version and x.outcome = 'accept' and x.capacity <> 'approver'
       order by x.decided_at desc, x.id desc limit 1) d on true
    left join lateral (select e.label from item_version_service o join editions e on e.seq = lower(o.editions)
       where o.version_id = p_version order by lower(o.editions) limit 1) f on true $$;

CREATE FUNCTION public.cl_version_stamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.created_xact := pg_current_xact_id();
  return new;
end $$;

CREATE FUNCTION public.edition_close_item(p_seq bigint, p_item text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update item_version_service set editions = int8range(lower(editions), p_seq) where item_id = p_item and upper_inf(editions);
  if not found then raise exception 'item % is not in service', p_item; end if;
end $$;

CREATE FUNCTION public.edition_close_vocab_term(p_seq bigint, p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not cl_is_admin_now() then
    raise exception 'only an administrator retires a vocabulary term' using errcode = 'insufficient_privilege';
  end if;
  update vocab_term_service set editions = int8range(lower(editions), p_seq) where term_key = p_key and upper_inf(editions);
  if not found then raise exception 'term % is not in service', p_key; end if;
end $$;

CREATE FUNCTION public.edition_content_digest(p_seq bigint) RETURNS bytea
    LANGUAGE sql STABLE
    AS $$
  select sha256(convert_to(coalesce(string_agg(line, E'\n' order by line), ''), 'UTF8')) from (
    select 'item:'  || s.item_id  || ':' || encode(v.content_digest, 'hex') as line
      from item_version_service s join item_versions v on v.id = s.version_id where s.editions @> p_seq
    union all
    select 'vocab:' || s.term_key || ':' || encode(v.content_digest, 'hex')
      from vocab_term_service s join vocab_term_versions v on v.id = s.version_id where s.editions @> p_seq
    union all
    select 'area:'  || area_id || ':' || state::text from area_state_service where editions @> p_seq
    union all
    select 'domain:' || term_key || ':' || area_id from source_domain_service where editions @> p_seq) x $$;

CREATE FUNCTION public.edition_lock() RETURNS void
    LANGUAGE sql
    AS $$ select pg_advisory_xact_lock(hashtextextended('context_layer.edition', 0)) $$;

CREATE FUNCTION public.edition_open(p_reason public.edition_reason, p_actor uuid, p_note text DEFAULT NULL::text, p_restores bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_day text := to_char(now() at time zone 'UTC', 'YYYY-MM-DD');
  v_n   int;
  v_seq bigint;
begin
  perform edition_lock();
  select coalesce(max(split_part(label, '.', 2)::int), 0) + 1 into v_n from editions where label like v_day || '.%';
  insert into editions (label, reason, actor_id, note, restores_seq)
  values (v_day || '.' || v_n, p_reason, p_actor, p_note, p_restores)
  returning seq into v_seq;
  return v_seq;
end $$;

CREATE FUNCTION public.edition_pin_source_domains(p_seq bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare closed int; opened int;
begin
  if not exists (select 1 from editions where seq = p_seq and sealed_at is null) then
    raise exception 'edition % is not open', p_seq using errcode = 'restrict_violation'; end if;
  -- Close what no longer holds, then open what is new.
  update source_domain_service c set editions = int8range(lower(c.editions), p_seq)
   where upper_inf(c.editions) and lower(c.editions) < p_seq
     and not exists (select 1 from cl_source_domains_now(p_seq) w where w.term_key = c.term_key and w.area_id = c.area_id);
  get diagnostics closed = row_count;
  insert into source_domain_service (term_key, area_id, editions)
    select w.term_key, w.area_id, int8range(p_seq, null) from cl_source_domains_now(p_seq) w
     where not exists (select 1 from source_domain_service c where c.term_key = w.term_key and upper_inf(c.editions));
  get diagnostics opened = row_count;
  return closed + opened;
end $$;

CREATE FUNCTION public.edition_publish(p_seq bigint, p_actor uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from editions where seq = p_seq and sealed_at is not null) then raise exception 'edition % is not sealed', p_seq; end if;
  insert into live_edition (seq, set_by) values (p_seq, p_actor)
  on conflict (singleton) do update set seq = excluded.seq, set_at = now(), set_by = excluded.set_by where live_edition.seq < excluded.seq;
end $$;

CREATE FUNCTION public.edition_restore(p_target bigint, p_actor uuid, p_note text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_seq bigint;
begin
  if not cl_is_admin(p_actor, now()) then raise exception 'only an administrator may go back to an edition' using errcode = 'insufficient_privilege'; end if;
  v_seq := edition_open('rollback', p_actor, p_note, p_target);
  update item_version_service s set editions = int8range(lower(s.editions), v_seq)
   where upper_inf(s.editions) and not exists (select 1 from item_version_service t where t.item_id = s.item_id and t.version_id = s.version_id and t.editions @> p_target);
  insert into item_version_service (item_id, version_id, editions)
    select t.item_id, t.version_id, int8range(v_seq, null) from item_version_service t
     where t.editions @> p_target and not exists (select 1 from item_version_service s where s.item_id = t.item_id and s.version_id = t.version_id and upper_inf(s.editions));
  update vocab_term_service s set editions = int8range(lower(s.editions), v_seq)
   where upper_inf(s.editions) and not exists (select 1 from vocab_term_service t where t.term_key = s.term_key and t.version_id = s.version_id and t.editions @> p_target);
  insert into vocab_term_service (term_key, version_id, editions)
    select t.term_key, t.version_id, int8range(v_seq, null) from vocab_term_service t
     where t.editions @> p_target and not exists (select 1 from vocab_term_service s where s.term_key = t.term_key and s.version_id = t.version_id and upper_inf(s.editions));
  update area_state_service s set editions = int8range(lower(s.editions), v_seq)
   where upper_inf(s.editions) and not exists (select 1 from area_state_service t where t.area_id = s.area_id and t.state = s.state and t.editions @> p_target);
  insert into area_state_service (area_id, state, editions)
    select t.area_id, t.state, int8range(v_seq, null) from area_state_service t
     where t.editions @> p_target and not exists (select 1 from area_state_service s where s.area_id = t.area_id and s.state = t.state and upper_inf(s.editions));
  update source_domain_service s set editions = int8range(lower(s.editions), v_seq)
   where upper_inf(s.editions) and not exists (select 1 from source_domain_service t where t.term_key = s.term_key and t.area_id = s.area_id and t.editions @> p_target);
  insert into source_domain_service (term_key, area_id, editions)
    select t.term_key, t.area_id, int8range(v_seq, null) from source_domain_service t
     where t.editions @> p_target and not exists (select 1 from source_domain_service s where s.term_key = t.term_key and s.area_id = t.area_id and upper_inf(s.editions));
  perform edition_seal(v_seq);
  perform edition_publish(v_seq, p_actor);
  return v_seq;
end $$;

CREATE FUNCTION public.edition_seal(p_seq bigint) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare e editions; d bytea;
begin
  perform edition_lock();
  select * into e from editions where seq = p_seq for update;
  if not found then raise exception 'edition % does not exist', p_seq; end if;
  if e.sealed_at is not null then raise exception 'edition % is already sealed', p_seq; end if;
  d := edition_content_digest(p_seq);
  if e.reason = 'rollback' and d <> (select digest from editions where seq = e.restores_seq) then
    raise exception 'rollback edition % does not equal edition %', p_seq, e.restores_seq using errcode = 'check_violation'; end if;
  update editions set digest = d, sealed_at = now() where seq = p_seq;
  return d;
end $$;

CREATE FUNCTION public.edition_serve_item_version(p_seq bigint, p_version uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v item_versions;
begin
  select * into v from item_versions where id = p_version;
  if not found then raise exception 'version % does not exist', p_version; end if;
  if exists (select 1 from item_version_service where item_id = v.item_id and upper_inf(editions) and lower(editions) = p_seq) then
    raise exception 'item % already changed in edition %', v.item_id, p_seq; end if;
  update item_version_service set editions = int8range(lower(editions), p_seq) where item_id = v.item_id and upper_inf(editions);
  insert into item_version_service (item_id, version_id, editions) values (v.item_id, p_version, int8range(p_seq, null));
end $$;

CREATE FUNCTION public.edition_serve_vocab_version(p_seq bigint, p_version uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v vocab_term_versions;
begin
  select * into v from vocab_term_versions where id = p_version;
  update vocab_term_service set editions = int8range(lower(editions), p_seq) where term_key = v.term_key and upper_inf(editions);
  insert into vocab_term_service (term_key, version_id, editions) values (v.term_key, p_version, int8range(p_seq, null));
end $$;

CREATE FUNCTION public.editions_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' or old.sealed_at is not null
     or (to_jsonb(new) - 'digest' - 'sealed_at') <> (to_jsonb(old) - 'digest' - 'sealed_at') then
    raise exception 'edition % is immutable', old.seq using errcode = 'restrict_violation'; end if;
  return new;
end $$;

CREATE FUNCTION public.item_bin_guard_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.restored_at is not null
     or (to_jsonb(new) - 'restored_by' - 'restored_at' - 'restored_via' - 'restored_edition' - 'restored_area'
           - 'rescue_proposal')
        <> (to_jsonb(old) - 'restored_by' - 'restored_at' - 'restored_via' - 'restored_edition' - 'restored_area'
           - 'rescue_proposal') then
    raise exception 'a Bin record may only be restored, once' using errcode = 'restrict_violation'; end if;
  return new;
end $$;

CREATE FUNCTION public.item_version_dimension_values_any() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists (select 1 from item_version_dimensions d
              where d.version_id = new.version_id and d.dimension_key = new.dimension_key) then
    raise exception 'a dimension with any value cannot also list its values' using errcode = 'check_violation';
  end if;
  return new;
end $$;

CREATE FUNCTION public.item_version_dimensions_check() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from vocab_terms t where t.key = new.dimension_key and t.kind = 'dimension') then
    raise exception '% is not a dimension', new.dimension_key using errcode = 'check_violation';
  end if;
  if exists (select 1 from item_version_dimension_values d
              where d.version_id = new.version_id and d.dimension_key = new.dimension_key) then
    raise exception 'a dimension with any value cannot also list its values' using errcode = 'check_violation';
  end if;
  return new;
end $$;

CREATE FUNCTION public.item_version_service_closing_authorized() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare e editions;
begin
  select * into e from editions where seq = upper(new.editions);
  if e.reason = 'rollback' then return null; end if;                                  -- edition_seal proves content equality
  if exists (select 1 from decisions d where d.item_version_id = new.version_id and d.outcome = 'retire'
             and d.area_id = (select area_id from item_versions where id = new.version_id)
             and (cl_is_admin(d.decided_by, d.decided_at)
                  or cl_has_area_role(d.decided_by, d.area_id, 'owner', d.decided_at))) then return null; end if;
  if exists (select 1 from item_version_service s where s.item_id = new.item_id and lower(s.editions) = upper(new.editions)) then return null; end if;
  if exists (select 1 from item_version_service s join item_version_replaces r on r.version_id = s.version_id
             where r.replaced_item_id = new.item_id and lower(s.editions) = upper(new.editions)) then return null; end if;
  raise exception 'item % left service at edition % without a retire decision or a replacing version', new.item_id, upper(new.editions)
    using errcode = 'check_violation';
end $$;

CREATE FUNCTION public.item_version_service_guard_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare problem text;
begin
  if not upper_inf(new.editions) then raise exception 'a row enters service open-ended' using errcode = 'check_violation'; end if;
  if exists (select 1 from editions e where e.seq = lower(new.editions) and e.sealed_at is not null) then
    raise exception 'edition % is sealed', lower(new.editions) using errcode = 'restrict_violation'; end if;
  problem := cl_item_version_problem(new.version_id);
  if problem is not null then
    raise exception 'version % cannot enter service: %', new.version_id, problem using errcode = 'check_violation'; end if;
  return new;
end $$;

CREATE FUNCTION public.item_version_service_guard_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.item_id <> old.item_id or new.version_id <> old.version_id or not upper_inf(old.editions)
     or lower(new.editions) <> lower(old.editions) or upper_inf(new.editions) or upper(new.editions) <= lower(new.editions) then
    raise exception 'item_version_service rows may only be closed' using errcode = 'restrict_violation'; end if;
  if exists (select 1 from editions e where e.seq = upper(new.editions) and e.sealed_at is not null) then
    raise exception 'edition % is sealed', upper(new.editions) using errcode = 'restrict_violation'; end if;
  return new;
end $$;

CREATE FUNCTION public.item_versions_mentions_match() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare tokens jsonb; rows_ jsonb; max_mentions int;
begin
  select coalesce(jsonb_agg(token || jsonb_build_object('field',field) order by field, (token->>'position')::int),'[]') into tokens
  from (values ('summary',new.summary_markup),('body',new.body_markup)) fields(field,markup),
       lateral jsonb_array_elements(cl_parse_mention_text(coalesce(markup,''))->'mentions') token;
  select coalesce(jsonb_agg(jsonb_build_object('field',field,'position',position,'label',label,
      'target',coalesce(term_key,'item:'||item_id,'area:'||area_id)) order by field::text,position),'[]') into rows_
    from item_version_mentions where version_id=new.id;
  select least(50,greatest(0,value::int)) into max_mentions from settings_current where key='limits.mentions_per_version';
  if jsonb_array_length(tokens)>coalesce(max_mentions,50) then
    raise exception 'at most % mentions are allowed',coalesce(max_mentions,50) using errcode='check_violation';
  end if;
  if tokens is distinct from rows_ then
    raise exception 'Mention rows do not match text' using errcode='check_violation';
  end if;
  if exists(select 1 from item_version_mentions where version_id=new.id and item_id=new.item_id) then
    raise exception 'item % mentions itself', new.item_id using errcode='check_violation';
  end if;
  return null;
end $$;

CREATE FUNCTION public.item_versions_scope_nonempty() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from item_version_metrics where version_id = new.id)
     and not exists (select 1 from item_version_dimension_values where version_id = new.id)
     and not exists (select 1 from item_version_dimensions where version_id = new.id) then
    raise exception 'item version % names no metric, no dimension value and no dimension', new.id using errcode = 'check_violation';
  end if;
  return null;
end $$;

CREATE FUNCTION public.outbox_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin perform pg_notify('cl_events', new.seq::text); return null; end $$;

CREATE FUNCTION public.overlay_bump() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  insert into serving_overlay (singleton, seq, changed_at) values (true, new.seq, now())
  on conflict (singleton) do update set seq = excluded.seq, changed_at = now();
  perform pg_notify('cl_overlay', new.seq::text);                -- other instances reload within a second; they also poll every 15 s
  return null;
end $$;

CREATE FUNCTION public.proposals_guard_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.discarded_at is not null then
    raise exception 'proposal % was discarded', old.id using errcode = 'check_violation';
  end if;
  if new.state is distinct from old.state
     and not exists (select 1 from proposal_transitions t where t.from_state = old.state and t.to_state = new.state) then
    raise exception 'proposal % cannot move from % to %', old.id, old.state, new.state using errcode = 'check_violation';
  end if;
  -- After submit the version is fixed, except for a review edit: a new version of the same item, edited by the person
  -- making this change, that supersedes the submitted one and keeps its content.
  if old.item_version_id is not null and new.item_version_id is distinct from old.item_version_id and old.state <> 'changes_requested'
     and not coalesce(
       old.state in ('submitted', 'in_review') and new.state = old.state and old.action in ('create', 'change')
       and new.item_id = old.item_id
       and exists (select 1 from item_versions v where v.id = new.item_version_id and v.item_id = old.item_id
                     and v.supersedes_version_id = old.item_version_id and v.edited_by = cl_person() and not v.is_recheck
                     and v.proposer_id is distinct from cl_person()
                     and exists (select 1 from item_versions o where o.id = old.item_version_id
                                   and cl_has_area_role(cl_person(), o.area_id, 'owner', now()))
                     and (v.area_id = (select o.area_id from item_versions o where o.id = old.item_version_id)
                          or cl_is_admin(cl_person(), now())
                          or cl_has_area_role(cl_person(), v.area_id, 'owner', now())))
       and cl_item_version_kept(new.item_version_id) = cl_item_version_kept(old.item_version_id), false) then
    raise exception 'proposal % version is fixed after submit', old.id using errcode = 'check_violation';
  end if;
  if new.revision = old.revision then new.revision := old.revision + 1; end if;
  return new;
end $$;

CREATE FUNCTION public.serving_items(p_seq bigint) RETURNS TABLE(item_id text, version_id uuid, version_no integer, kind public.item_kind, area_id text, title text, summary text, body text, risk public.risk_level, claim public.claim_level, audience_groups text[], valid_from date, valid_until date, review_date date, owner_id uuid, content_digest bytea, metrics text[], value_keys text[], ref_marks jsonb, conflicts text[], replaces text[], evidence jsonb, dimension_keys text[], not_to_conclude text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.item_id, v.id, v.version_no, i.kind, v.area_id, v.title, v.summary, v.body, v.risk, v.claim, v.audience_groups,
         v.valid_from, v.valid_until, v.review_date, v.owner_id, v.content_digest,
         coalesce((select array_agg(m.metric_key order by m.metric_key) from item_version_metrics m where m.version_id = v.id), '{}'),
         coalesce((select array_agg(d.value_key order by d.value_key) from item_version_dimension_values d where d.version_id = v.id), '{}'),
         coalesce((select jsonb_object_agg(r.definition_ref, r.change_mark) from item_version_refs r where r.version_id = v.id), '{}'),
         coalesce((select array_agg(c.other_item_id order by c.other_item_id) from item_version_conflicts c where c.version_id = v.id), '{}'),
         coalesce((select array_agg(x.replaced_item_id order by x.replaced_item_id) from item_version_replaces x where x.version_id = v.id), '{}'),
         coalesce((select jsonb_agg(jsonb_build_object('url', ev.url, 'quote', ev.quote, 'read_on', ev.read_on) order by ev.position) from item_version_evidence ev where ev.version_id = v.id), '[]'),
         coalesce((select array_agg(d.dimension_key order by d.dimension_key) from item_version_dimensions d where d.version_id = v.id), '{}'),
         v.not_to_conclude
    from item_version_service s
    join item_versions v on v.id = s.version_id
    join items i on i.id = s.item_id
   where s.editions @> p_seq $$;

CREATE FUNCTION public.serving_links(p_seq bigint) RETURNS TABLE(from_item text, rel text, to_kind text, to_id text, label text, definition_ref text, change_mark text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.item_id, l.rel, l.to_kind, l.to_id, l.label, l.definition_ref, l.change_mark
    from item_version_service s join v_version_links l on l.version_id = s.version_id
   where s.editions @> p_seq $$;

CREATE FUNCTION public.serving_metadata(p_seq bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'areas', coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'team',a.owner_team,
        'summary',a.summary,'description',a.description) order by a.id)
      from areas a where a.archived_at is null or exists (select 1 from item_version_service s
        join item_versions v on v.id=s.version_id where s.editions @> p_seq and v.area_id=a.id)), '[]'),
    'retired', coalesce((select jsonb_agg(jsonb_build_object('id',x.item_id,'areaId',v.area_id,
      'audience',v.audience_groups,'validity',jsonb_build_object('start',v.valid_from,'end',v.valid_until),
      'replacedBy',(select r.item_id from item_version_replaces rpl join item_versions r on r.id=rpl.version_id
        join item_version_service rs on rs.version_id=r.id where rpl.replaced_item_id=x.item_id and rs.editions @> p_seq order by r.item_id limit 1)))
      from (select distinct on (item_id) item_id,version_id,editions from item_version_service
        where lower(editions)<=p_seq order by item_id,lower(editions) desc) x
      join item_versions v on v.id=x.version_id where not (x.editions @> p_seq)), '[]'))
$$;

CREATE FUNCTION public.serving_report_gap(p_key text, p_area text, p_metrics text[], p_values text[], p_dimensions text[], p_month date, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare topic uuid;
begin
  if p_note is not null and char_length(p_note)>500 then raise exception 'note too long'; end if;
  insert into topics (key,area_id,metric_keys,value_keys,dimension_keys,month)
    values (p_key,p_area,p_metrics,p_values,coalesce(p_dimensions,'{}'),p_month)
    on conflict (key) do nothing;
  select id into topic from topics where key=p_key;
  return cl_gap_touch(topic, 'missing', 2::smallint, now(), null, 1, p_note, 'report_gap');
end $$;

CREATE FUNCTION public.serving_reviews(p_seq bigint) RETURNS TABLE(item_id text, accepted_on date, accepted_as public.decision_capacity, accepted_area text, first_edition text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.item_id, r.accepted_on, r.accepted_as, r.accepted_area, r.first_edition
    from item_version_service s cross join lateral cl_version_review(s.version_id) r
   where s.editions @> p_seq $$;

CREATE FUNCTION public.serving_source_domains(p_seq bigint) RETURNS TABLE(key text, area_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select term_key, area_id from source_domain_service where editions @> p_seq $$;

CREATE FUNCTION public.serving_vocabulary(p_seq bigint) RETURNS TABLE(key text, kind public.term_kind, parent_key text, name text, aliases text[], area_id text, definition_refs text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.key, t.kind, t.parent_key, v.name, v.aliases, v.area_id,
         coalesce((select array_agg(r.definition_ref order by r.definition_ref collate "C")
                     from vocab_term_refs r where r.version_id = v.id), '{}')
    from vocab_term_service s join vocab_term_versions v on v.id = s.version_id join vocab_terms t on t.key = s.term_key
   where s.editions @> p_seq $$;

CREATE FUNCTION public.vocab_term_service_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v vocab_term_versions; ok boolean;
begin
  if tg_op = 'INSERT' then
    if not upper_inf(new.editions) then raise exception 'a row enters service open-ended' using errcode = 'check_violation'; end if;
    if exists (select 1 from editions e where e.seq = lower(new.editions) and e.sealed_at is not null) then
      raise exception 'edition % is sealed', lower(new.editions) using errcode = 'restrict_violation'; end if;
    select * into v from vocab_term_versions where id = new.version_id;
    select exists (select 1 from decisions d where d.vocab_version_id = v.id and d.outcome = 'accept'
        and (d.decided_by <> v.proposer_id or v.proposer_id is null or cl_decides_own(d.decided_by, v.area_id, d.decided_at))
        and ((v.area_id is not null and d.capacity in ('owner','deputy')
              and cl_has_area_role(d.decided_by, v.area_id, 'owner', d.decided_at))
          or (d.capacity = 'administrator' and cl_is_admin(d.decided_by, d.decided_at)))) into ok;
    if not ok and not exists (select 1 from editions e where e.seq = lower(new.editions) and e.reason in ('bootstrap','rollback')) then
      raise exception 'vocabulary version % has no accept decision by an owner of its area or an administrator', v.id using errcode = 'check_violation'; end if;
    return new;
  end if;
  if new.version_id <> old.version_id or not upper_inf(old.editions) or lower(new.editions) <> lower(old.editions) or upper_inf(new.editions) then
    raise exception 'vocab_term_service rows may only be closed' using errcode = 'restrict_violation'; end if;
  return new;
end $$;

CREATE TABLE auth.dev_people (
    person_id uuid NOT NULL
);

CREATE TABLE auth.oauth_clients (
    id text NOT NULL,
    kind text NOT NULL,
    name text NOT NULL,
    redirect_uris text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT oauth_clients_id_check CHECK (((char_length(id) >= 1) AND (char_length(id) <= 512))),
    CONSTRAINT oauth_clients_kind_check CHECK ((kind = ANY (ARRAY['metadata_document'::text, 'registered'::text]))),
    CONSTRAINT oauth_clients_name_check CHECK (((char_length(name) BETWEEN 1 AND 100) AND (btrim(name) <> ''::text))),
    CONSTRAINT oauth_clients_redirect_uris_check CHECK (((cardinality(redirect_uris) >= 1) AND (cardinality(redirect_uris) <= 10)))
);

CREATE TABLE auth.oauth_codes (
    code_hash text NOT NULL,
    client_id text NOT NULL,
    person_id uuid NOT NULL,
    redirect_uri text NOT NULL,
    scopes text[] NOT NULL,
    code_challenge text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    grant_id uuid,
    CONSTRAINT oauth_codes_code_challenge_check CHECK ((code_challenge ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT oauth_codes_code_hash_check CHECK ((code_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT oauth_codes_scopes_check CHECK (((scopes <@ ARRAY['read'::text, 'feedback'::text, 'propose'::text]) AND (cardinality(scopes) >= 1)))
);

CREATE TABLE auth.oauth_grants (
    id uuid DEFAULT uuidv7() NOT NULL,
    person_id uuid NOT NULL,
    client_id text NOT NULL,
    scopes text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    last_used_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_reason text,
    CONSTRAINT oauth_grants_check CHECK (((revoked_at IS NULL) = (revoked_reason IS NULL))),
    CONSTRAINT oauth_grants_revoked_reason_check CHECK ((revoked_reason = ANY (ARRAY['disconnected'::text, 'disconnected_by_admin'::text, 'refresh_reuse'::text, 'code_reuse'::text, 'revoked_by_client'::text, 'person_inactive'::text]))),
    CONSTRAINT oauth_grants_scopes_check CHECK (((scopes <@ ARRAY['read'::text, 'feedback'::text, 'propose'::text]) AND (cardinality(scopes) >= 1)))
);

CREATE TABLE auth.oauth_refresh_tokens (
    token_hash text NOT NULL,
    grant_id uuid NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT oauth_refresh_tokens_token_hash_check CHECK ((token_hash ~ '^[a-f0-9]{64}$'::text))
);

CREATE TABLE auth.oauth_requests (
    id_hash text NOT NULL,
    browser_hash text NOT NULL,
    client_id text NOT NULL,
    client_kind text NOT NULL,
    client_name text NOT NULL,
    redirect_uri text NOT NULL,
    scopes text[] NOT NULL,
    state text,
    code_challenge text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT oauth_requests_browser_hash_check CHECK ((browser_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT oauth_requests_client_id_check CHECK (((char_length(client_id) >= 1) AND (char_length(client_id) <= 512))),
    CONSTRAINT oauth_requests_client_kind_check CHECK ((client_kind = ANY (ARRAY['metadata_document'::text, 'registered'::text]))),
    CONSTRAINT oauth_requests_client_name_check CHECK (((char_length(client_name) >= 1) AND (char_length(client_name) <= 100))),
    CONSTRAINT oauth_requests_code_challenge_check CHECK ((code_challenge ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT oauth_requests_id_hash_check CHECK ((id_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT oauth_requests_redirect_uri_check CHECK ((char_length(redirect_uri) <= 512)),
    CONSTRAINT oauth_requests_scopes_check CHECK (((scopes <@ ARRAY['read'::text, 'feedback'::text, 'propose'::text]) AND (cardinality(scopes) >= 1))),
    CONSTRAINT oauth_requests_state_check CHECK ((char_length(state) <= 512))
);

CREATE TABLE auth.sessions (
    token_hash text NOT NULL,
    person_id uuid NOT NULL,
    csrf_token text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sessions_token_hash_check CHECK ((token_hash ~ '^[a-f0-9]{64}$'::text))
);

CREATE TABLE public.area_assignments (
    area_id text NOT NULL,
    person_id uuid NOT NULL,
    role public.area_role NOT NULL,
    valid_at tstzrange DEFAULT tstzrange(now(), NULL::timestamp with time zone) NOT NULL,
    granted_by uuid
);

CREATE TABLE public.area_deletions (
    id uuid DEFAULT uuidv7() NOT NULL,
    area_id text NOT NULL,
    deleted_by uuid NOT NULL,
    deleted_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text,
    edition bigint,
    contents jsonb NOT NULL,
    recipients uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    restored_by uuid,
    restored_at timestamp with time zone,
    restored_edition bigint,
    CONSTRAINT area_deletions_check CHECK (((restored_at IS NULL) = (restored_by IS NULL))),
    CONSTRAINT area_deletions_check1 CHECK (((restored_edition IS NULL) OR (restored_at IS NOT NULL))),
    CONSTRAINT area_deletions_reason_check CHECK (((reason IS NULL) OR ((char_length(btrim(reason)) >= 1) AND (char_length(btrim(reason)) <= 500))))
);

CREATE TABLE public.area_state_service (
    area_id text NOT NULL,
    state public.area_state NOT NULL,
    editions int8range NOT NULL,
    CONSTRAINT area_state_service_editions_check CHECK (((NOT isempty(editions)) AND lower_inc(editions) AND (NOT lower_inf(editions))))
);

CREATE TABLE public.areas (
    id text NOT NULL,
    name text NOT NULL,
    owner_team text,
    chat_channel text,
    review_days integer DEFAULT 2 NOT NULL,
    label text DEFAULT 'gray'::text NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    archived_at timestamp with time zone,
    revision integer DEFAULT 1 NOT NULL,
    summary text DEFAULT ''::text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    CONSTRAINT areas_description_check CHECK (((char_length(description) <= 1500) AND (translate(description, '
'::text, ''::text) !~ '[[:cntrl:]]'::text) AND (description = btrim(description, ' 
'::text)))),
    CONSTRAINT areas_id_check CHECK ((id ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
    CONSTRAINT areas_label_check CHECK ((label = ANY (ARRAY['teal'::text, 'sky'::text, 'indigo'::text, 'violet'::text, 'pink'::text, 'lime'::text, 'stone'::text, 'gray'::text]))),
    CONSTRAINT areas_review_days_check CHECK (((review_days >= 1) AND (review_days <= 30))),
    CONSTRAINT areas_revision_check CHECK ((revision >= 1)),
    CONSTRAINT areas_summary_check CHECK (((char_length(summary) <= 160) AND (summary !~ '[[:cntrl:]]'::text) AND (summary = btrim(summary))))
);

CREATE TABLE public.assistant_case_tries (
    id uuid DEFAULT uuidv7() NOT NULL,
    run_id uuid NOT NULL,
    case_id text NOT NULL,
    try smallint NOT NULL,
    state text DEFAULT 'running'::text NOT NULL,
    passed boolean,
    failure_kind text,
    problems jsonb DEFAULT '[]'::jsonb NOT NULL,
    checks jsonb DEFAULT '{}'::jsonb NOT NULL,
    verdict jsonb,
    turns jsonb DEFAULT '[]'::jsonb NOT NULL,
    first_text_ms integer,
    first_sentence_ms integer,
    total_ms integer,
    cost_micros bigint DEFAULT 0 NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT assistant_case_tries_case_id_check CHECK ((case_id ~ '^[a-z0-9][a-z0-9-]{2,80}$'::text)),
    CONSTRAINT assistant_case_tries_checks_check CHECK ((jsonb_typeof(checks) = 'object'::text)),
    CONSTRAINT assistant_case_tries_cost_micros_check CHECK ((cost_micros >= 0)),
    CONSTRAINT assistant_case_tries_failure_kind_check CHECK ((failure_kind = ANY (ARRAY['throttled'::text, 'provider'::text, 'judge'::text, 'error'::text]))),
    CONSTRAINT assistant_case_tries_first_sentence_ms_check CHECK ((first_sentence_ms >= 0)),
    CONSTRAINT assistant_case_tries_first_text_ms_check CHECK ((first_text_ms >= 0)),
    CONSTRAINT assistant_case_tries_problems_check CHECK ((jsonb_typeof(problems) = 'array'::text)),
    CONSTRAINT assistant_case_tries_state_check CHECK ((state = ANY (ARRAY['running'::text, 'finished'::text, 'failed'::text]))),
    CONSTRAINT assistant_case_tries_total_ms_check CHECK ((total_ms >= 0)),
    CONSTRAINT assistant_case_tries_try_check CHECK ((try >= 1)),
    CONSTRAINT assistant_case_tries_turns_check CHECK ((jsonb_typeof(turns) = 'array'::text))
);

CREATE TABLE public.assistant_ratings (
