    CONSTRAINT assistant_ratings_created_hour_check CHECK ((created_hour = date_trunc('hour'::text, created_hour, 'UTC'::text))),
    CONSTRAINT assistant_ratings_id_check CHECK ((uuid_extract_version(id) = 4)),
    CONSTRAINT assistant_ratings_verdict_check CHECK ((verdict = ANY (ARRAY['helpful'::public.feedback_verdict, 'wrong'::public.feedback_verdict])))
);

CREATE TABLE public.audit_log (
