    actor_id uuid,
    actor_kind text NOT NULL,
    action text NOT NULL,
    area_id text,
    subject_type text,
    subject_id text,
    request_id text DEFAULT NULLIF(current_setting('cl.request_id'::text, true), ''::text),
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    prev_hash bytea,
    hash bytea NOT NULL,
    batch_id uuid,
    reason text,
    source text,
    CONSTRAINT audit_log_action_check CHECK ((action ~ '^[a-z_]+\.[a-z_]+$'::text)),
    CONSTRAINT audit_log_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['person'::text, 'system'::text, 'service'::text]))),
    CONSTRAINT audit_log_check CHECK (((actor_kind = 'person'::text) = (actor_id IS NOT NULL))),
    CONSTRAINT audit_log_reason_check CHECK (((reason IS NULL) OR ((char_length(reason) >= 1) AND (char_length(reason) <= 500)))),
    CONSTRAINT audit_log_source_check CHECK ((source = 'named'::text))
);

ALTER TABLE public.audit_log ALTER COLUMN seq ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.audit_log_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

