    note text,
    restores_seq bigint,
    digest bytea,
    sealed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT editions_check CHECK (((reason = 'rollback'::public.edition_reason) = (restores_seq IS NOT NULL))),
    CONSTRAINT editions_check1 CHECK (((digest IS NULL) = (sealed_at IS NULL))),
    CONSTRAINT editions_digest_check CHECK ((length(digest) = 32)),
    CONSTRAINT editions_label_check CHECK ((label ~ '^\d{4}-\d{2}-\d{2}\.\d+$'::text)),
    CONSTRAINT editions_note_check CHECK ((char_length(note) <= 500))
);

ALTER TABLE public.editions ALTER COLUMN seq ADD GENERATED ALWAYS AS IDENTITY (
