    CONSTRAINT eval_runs_cost_ceiling_micros_check CHECK ((cost_ceiling_micros >= 0)),
    CONSTRAINT eval_runs_failure_check CHECK ((char_length(failure) <= 500)),
    CONSTRAINT eval_runs_tries_check CHECK ((tries >= 1)),
