    CONSTRAINT gap_notes_created_hour_check CHECK ((created_hour = date_trunc('hour'::text, created_hour, 'UTC'::text))),
    CONSTRAINT gap_notes_delete_after_hour CHECK ((delete_after = date_trunc('hour'::text, delete_after, 'UTC'::text))),
    CONSTRAINT gap_notes_id_check CHECK ((uuid_extract_version(id) = 4)),
    CONSTRAINT gap_notes_note_check CHECK (((char_length(note) >= 1) AND (char_length(note) <= 500))),
