    CONSTRAINT gap_report_keys_expires_hour_check CHECK ((expires_hour = date_trunc('hour'::text, expires_hour, 'UTC'::text))),
    CONSTRAINT gap_report_keys_request_digest_check CHECK ((octet_length(request_digest) = 32)),
    CONSTRAINT gap_report_keys_retry_digest_check CHECK ((octet_length(retry_digest) = 32))
