    CONSTRAINT golden_questions_id_check CHECK ((id ~ '^[a-z0-9][a-z0-9-]{2,80}$'::text)),
    CONSTRAINT golden_questions_set_aside_reason_check CHECK ((char_length(set_aside_reason) <= 500)),
    CONSTRAINT golden_questions_wordings_check CHECK (((jsonb_typeof(wordings) = 'array'::text) AND (jsonb_array_length(wordings) >= 2)))
);

