    CONSTRAINT item_version_evidence_quote_check CHECK (((char_length(quote) >= 1) AND (char_length(quote) <= 500))),
    CONSTRAINT item_version_evidence_url_check CHECK (((url ~ '^https?://'::text) AND (char_length(url) <= 2000)))
);

