CREATE TABLE public.item_versions (
    id uuid DEFAULT uuidv7() NOT NULL,
    item_id text NOT NULL,
    version_no integer NOT NULL,
    supersedes_version_id uuid,
    area_id text NOT NULL,
    title text NOT NULL,
    summary text NOT NULL,
    body text,
    risk public.risk_level NOT NULL,
    claim public.claim_level DEFAULT 'fact_only'::public.claim_level NOT NULL,
    claim_authority text,
    claim_quote text,
    audience_groups text[],
    owner_id uuid,
    proposer_id uuid NOT NULL,
    edited_by uuid,
    created_via public.creation_channel NOT NULL,
    valid_from date NOT NULL,
    valid_until date,
    validity daterange GENERATED ALWAYS AS (daterange(valid_from, valid_until, '[)'::text)) STORED,
    review_date date,
    not_to_conclude text DEFAULT 'cause not proven'::text NOT NULL,
    is_recheck boolean DEFAULT false NOT NULL,
    content_digest bytea NOT NULL,
    core_digest bytea NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    search tsvector GENERATED ALWAYS AS (((setweight(to_tsvector('simple'::regconfig, title), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, summary), 'B'::"char")) || setweight(to_tsvector('simple'::regconfig, COALESCE(body, ''::text)), 'C'::"char"))) STORED,
    summary_markup text,
    body_markup text,
    created_xact xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT item_versions_audience_groups_check CHECK (((audience_groups IS NULL) OR (cardinality(audience_groups) > 0))),
    CONSTRAINT item_versions_body_check CHECK (((body IS NULL) OR (char_length(body) <= 20000))),
    CONSTRAINT item_versions_body_markup_plain CHECK (((body_markup IS NULL) OR ((body IS NOT NULL) AND (public.cl_strip_mentions(body_markup) = body)))),
    CONSTRAINT item_versions_check CHECK (((valid_until IS NULL) OR (valid_until > valid_from))),
    CONSTRAINT item_versions_check1 CHECK (((valid_until IS NOT NULL) OR (review_date IS NOT NULL))),
    CONSTRAINT item_versions_check2 CHECK (((claim = 'effect_stated'::public.claim_level) = ((claim_authority IS NOT NULL) AND (claim_quote IS NOT NULL)))),
    CONSTRAINT item_versions_claim_authority_check CHECK (((claim_authority IS NULL) OR (char_length(claim_authority) <= 200))),
    CONSTRAINT item_versions_claim_quote_check CHECK (((claim_quote IS NULL) OR (char_length(claim_quote) <= 500))),
    CONSTRAINT item_versions_content_digest_check CHECK ((length(content_digest) = 32)),
    CONSTRAINT item_versions_core_digest_check CHECK ((length(core_digest) = 32)),
    CONSTRAINT item_versions_summary_check CHECK ((char_length(summary) <= 280)),
    CONSTRAINT item_versions_summary_markup_plain CHECK (((summary_markup IS NULL) OR (public.cl_strip_mentions(summary_markup) = summary))),
    CONSTRAINT item_versions_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 200))),
    CONSTRAINT item_versions_version_no_check CHECK ((version_no >= 1))
);

CREATE TABLE public.items (
    id text DEFAULT public.cl_short_id('itm'::text) NOT NULL,
    kind public.item_kind NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT items_id_check CHECK ((id ~ '^itm_[0-9a-z]{8,16}$'::text))
);

CREATE TABLE public.job_heartbeats (
    job text NOT NULL,
    expected_every interval NOT NULL,
    last_started timestamp with time zone,
    last_succeeded timestamp with time zone,
    last_error_at timestamp with time zone,
    last_error text,
    runs_ok bigint DEFAULT 0 NOT NULL,
    runs_failed bigint DEFAULT 0 NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.live_edition (
    singleton boolean DEFAULT true NOT NULL,
    seq bigint NOT NULL,
    set_at timestamp with time zone DEFAULT now() NOT NULL,
    set_by uuid,
    CONSTRAINT live_edition_singleton_check CHECK (singleton)
);

CREATE TABLE public.llm_spend_daily (
    day date NOT NULL,
    person_id uuid NOT NULL,
    feature text NOT NULL,
    tokens_in bigint DEFAULT 0 NOT NULL,
    tokens_out bigint DEFAULT 0 NOT NULL,
    cost_micros bigint DEFAULT 0 NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    estimated_calls bigint DEFAULT 0 NOT NULL,
    web_searches bigint DEFAULT 0 NOT NULL,
    web_reads bigint DEFAULT 0 NOT NULL
);

CREATE TABLE public.llm_spend_monthly (
    month date NOT NULL,
    feature text NOT NULL,
    calls bigint DEFAULT 0 NOT NULL,
    cost_micros bigint DEFAULT 0 NOT NULL,
    estimated_calls bigint DEFAULT 0 NOT NULL,
    provider text NOT NULL,
    web_searches bigint DEFAULT 0 NOT NULL,
    web_reads bigint DEFAULT 0 NOT NULL
);

CREATE TABLE public.mcp_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    hour timestamp with time zone DEFAULT date_trunc('hour'::text, now(), 'UTC'::text) NOT NULL,
    client_label text NOT NULL,
    tool text NOT NULL,
    status text NOT NULL,
    duration_ms integer,
    edition_seq bigint,
    response_bytes integer,
    app_family text DEFAULT 'unknown'::text NOT NULL,
    result_status text,
    CONSTRAINT mcp_requests_app_family_check CHECK ((app_family = ANY (ARRAY['claude_code'::text, 'claude_ai'::text, 'chatgpt'::text, 'codex'::text, 'cursor'::text, 'vscode_copilot'::text, 'windsurf'::text, 'gemini_cli'::text, 'goose'::text, 'heed'::text, 'other'::text, 'unknown'::text]))),
    CONSTRAINT mcp_requests_client_label_check CHECK ((client_label ~ '^[a-z0-9_.-]{1,40}$'::text)),
    CONSTRAINT mcp_requests_hour_check CHECK ((hour = date_trunc('hour'::text, hour, 'UTC'::text))),
    CONSTRAINT mcp_requests_id_check CHECK ((uuid_extract_version(id) = 4)),
    CONSTRAINT mcp_requests_result_status_check CHECK ((result_status = ANY (ARRAY['matched'::text, 'need_more_detail'::text, 'no_match'::text]))),
    CONSTRAINT mcp_requests_status_check CHECK ((status = ANY (ARRAY['ok'::text, 'error'::text, 'invalid_input'::text, 'rate_limited'::text, 'forbidden'::text, 'unauthorized'::text])))
)
PARTITION BY RANGE (hour);

CREATE TABLE public.model_calls (
    id uuid DEFAULT uuidv7() NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    feature text NOT NULL,
    run_id uuid NOT NULL,
    cell_id uuid,
    case_try_id uuid,
    role text NOT NULL,
    provider text NOT NULL,
    model text NOT NULL,
    attempt smallint NOT NULL,
    outcome text NOT NULL,
    http_status smallint,
    tokens_in integer DEFAULT 0 NOT NULL,
    tokens_out integer DEFAULT 0 NOT NULL,
    cache_read integer DEFAULT 0 NOT NULL,
    cache_write integer DEFAULT 0 NOT NULL,
    reasoning integer DEFAULT 0 NOT NULL,
    latency_ms integer NOT NULL,
    cost_micros bigint DEFAULT 0 NOT NULL,
    estimated boolean DEFAULT false NOT NULL,
    CONSTRAINT model_calls_attempt_check CHECK ((attempt >= 1)),
    CONSTRAINT model_calls_cache_read_check CHECK ((cache_read >= 0)),
    CONSTRAINT model_calls_cache_write_check CHECK ((cache_write >= 0)),
    CONSTRAINT model_calls_cost_micros_check CHECK ((cost_micros >= 0)),
    CONSTRAINT model_calls_feature_check CHECK ((feature = ANY (ARRAY['eval'::text, 'assistant'::text]))),
    CONSTRAINT model_calls_latency_ms_check CHECK ((latency_ms >= 0)),
    CONSTRAINT model_calls_model_check CHECK ((char_length(model) <= 100)),
    CONSTRAINT model_calls_outcome_check CHECK ((outcome = ANY (ARRAY['ok'::text, 'throttled'::text, 'failed'::text, 'aborted'::text]))),
    CONSTRAINT model_calls_provider_check CHECK ((char_length(provider) <= 40)),
    CONSTRAINT model_calls_reasoning_check CHECK ((reasoning >= 0)),
    CONSTRAINT model_calls_role_check CHECK ((role = ANY (ARRAY['eval_answer'::text, 'judge'::text, 'assistant'::text, 'test_authoring'::text]))),
    CONSTRAINT model_calls_tokens_in_check CHECK ((tokens_in >= 0)),
    CONSTRAINT model_calls_tokens_out_check CHECK ((tokens_out >= 0))
);

CREATE TABLE public.notification_prefs (
    person_id uuid NOT NULL,
    channel text NOT NULL,
    kind text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    CONSTRAINT notification_prefs_channel_check CHECK ((channel = ANY (ARRAY['inbox'::text, 'chat'::text, 'email'::text])))
);

ALTER TABLE public.outbox_events ALTER COLUMN seq ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.outbox_events_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE SEQUENCE public.outbox_relay_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE public.overlay_events (
    seq bigint NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    kind text NOT NULL,
    scope text NOT NULL,
    area_id text,
    item_id text,
    flag public.source_flag,
    reason text,
    actor_id uuid,
    snapshot_id uuid,
    CONSTRAINT overlay_events_check CHECK ((((scope = 'all'::text) AND (area_id IS NULL) AND (item_id IS NULL)) OR ((scope = 'area'::text) AND (area_id IS NOT NULL) AND (item_id IS NULL)) OR ((scope = 'item'::text) AND (item_id IS NOT NULL)))),
    CONSTRAINT overlay_events_check1 CHECK (((kind = ANY (ARRAY['flag_on'::text, 'flag_off'::text])) = ((flag IS NOT NULL) AND (scope = 'item'::text)))),
    CONSTRAINT overlay_events_kind_check CHECK ((kind = ANY (ARRAY['flag_on'::text, 'flag_off'::text, 'stop_on'::text, 'stop_off'::text]))),
    CONSTRAINT overlay_events_reason_check CHECK ((char_length(reason) <= 500)),
    CONSTRAINT overlay_events_scope_check CHECK ((scope = ANY (ARRAY['all'::text, 'area'::text, 'item'::text])))
);

ALTER TABLE public.overlay_events ALTER COLUMN seq ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.overlay_events_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.people (
    id uuid DEFAULT uuidv7() NOT NULL,
    email text NOT NULL,
    display_name text NOT NULL,
    avatar_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deactivated_at timestamp with time zone,
    erased_at timestamp with time zone,
    last_signed_in_at timestamp with time zone,
    CONSTRAINT people_display_name_check CHECK ((btrim(display_name) <> ''::text)),
    CONSTRAINT people_email_check CHECK ((email = lower(email)))
);

CREATE TABLE public.proposal_events (
    id uuid DEFAULT uuidv7() NOT NULL,
    proposal_id uuid NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    actor_id uuid,
    kind text NOT NULL,
    data jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT proposal_events_kind_check CHECK ((kind ~ '^[a-z_]+$'::text))
);

CREATE TABLE public.proposal_tests (
    proposal_id uuid NOT NULL,
    question_id text NOT NULL,
    attached_hour timestamp with time zone DEFAULT date_trunc('hour'::text, now(), 'UTC'::text) NOT NULL,
    CONSTRAINT proposal_tests_attached_hour CHECK ((attached_hour = date_trunc('hour'::text, attached_hour, 'UTC'::text)))
);

CREATE TABLE public.proposal_transitions (
    from_state public.proposal_state NOT NULL,
    to_state public.proposal_state NOT NULL
);

CREATE TABLE public.proposals (
    id uuid DEFAULT uuidv7() NOT NULL,
    number bigint NOT NULL,
    subject public.proposal_subject DEFAULT 'item'::public.proposal_subject NOT NULL,
    action public.proposal_action NOT NULL,
    state public.proposal_state DEFAULT 'draft'::public.proposal_state NOT NULL,
    area_id text,
    item_id text,
    item_version_id uuid,
    vocab_version_id uuid,
    proposer_id uuid NOT NULL,
    channel public.creation_channel NOT NULL,
    draft jsonb,
    draft_saved_at timestamp with time zone,
    reason text,
    claimed_by uuid,
    claimed_at timestamp with time zone,
    due_at timestamp with time zone,
    derived_from uuid,
    source_gap_id uuid,
    import_batch_id uuid,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_at timestamp with time zone,
    closed_at timestamp with time zone,
    draft_findings jsonb DEFAULT '[]'::jsonb NOT NULL,
    discarded_at timestamp with time zone,
    provenance jsonb,
    answers_round uuid,
    CONSTRAINT proposals_check CHECK (((subject = 'item'::public.proposal_subject) = (vocab_version_id IS NULL))),
    CONSTRAINT proposals_check1 CHECK (((state = 'draft'::public.proposal_state) OR ((item_version_id IS NOT NULL) OR (vocab_version_id IS NOT NULL) OR (action = 'retire'::public.proposal_action)))),
    CONSTRAINT proposals_check2 CHECK (((action <> 'retire'::public.proposal_action) OR (item_id IS NOT NULL))),
    CONSTRAINT proposals_check3 CHECK (((state = ANY (ARRAY['accepted'::public.proposal_state, 'rejected'::public.proposal_state, 'withdrawn'::public.proposal_state])) = (closed_at IS NOT NULL))),
    CONSTRAINT proposals_discarded_draft CHECK (((discarded_at IS NULL) OR (state = 'draft'::public.proposal_state))),
    CONSTRAINT proposals_item_area CHECK (((subject = 'vocabulary'::public.proposal_subject) OR (area_id IS NOT NULL))),
    CONSTRAINT proposals_provenance_check CHECK (((provenance IS NULL) OR ((jsonb_typeof(provenance) = 'object'::text) AND ((provenance ->> 'by'::text) = ANY (ARRAY['agent'::text, 'assistant'::text])) AND (jsonb_typeof((provenance -> 'fields'::text)) = 'object'::text) AND (jsonb_typeof((provenance -> 'flags'::text)) = 'array'::text)))),
    CONSTRAINT proposals_reason_check CHECK ((char_length(reason) <= 500))
);

ALTER TABLE public.proposals ALTER COLUMN number ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.proposals_number_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.retrieval_results (
    run_id uuid NOT NULL,
    question_id text NOT NULL,
    question_revision integer NOT NULL,
    area_id text NOT NULL,
    split public.question_split NOT NULL,
    passed boolean NOT NULL,
    checks jsonb NOT NULL,
    wordings jsonb NOT NULL,
    delivery_digest bytea NOT NULL,
    CONSTRAINT retrieval_results_wordings_check CHECK ((jsonb_typeof(wordings) = 'array'::text))
);

CREATE TABLE public.retrieval_runs (
    id uuid DEFAULT uuidv7() NOT NULL,
    edition_seq bigint NOT NULL,
    overlay_seq bigint NOT NULL,
    as_of date NOT NULL,
    trigger public.retrieval_trigger NOT NULL,
    test_set_digest bytea NOT NULL,
    questions integer NOT NULL,
    passed integer NOT NULL,
    set_aside jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT retrieval_runs_check CHECK (((passed >= 0) AND (passed <= questions))),
    CONSTRAINT retrieval_runs_questions_check CHECK ((questions >= 0))
);

CREATE TABLE public.saved_views (
    id uuid DEFAULT uuidv7() NOT NULL,
    person_id uuid NOT NULL,
    name text NOT NULL,
    query text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT saved_views_query_check CHECK ((char_length(query) <= 2000))
);

CREATE TABLE public.serving_overlay (
    singleton boolean DEFAULT true NOT NULL,
    seq bigint DEFAULT 0 NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT serving_overlay_singleton_check CHECK (singleton)
);

CREATE TABLE public.settings_versions (
    key text NOT NULL,
    version integer NOT NULL,
    value jsonb NOT NULL,
    changed_by uuid,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text,
    CONSTRAINT settings_versions_key_check CHECK ((key ~ '^[a-z_]+(\.[a-z_]+)*$'::text))
);

CREATE VIEW public.settings_current AS
 SELECT DISTINCT ON (key) key,
    version,
    value,
    changed_at
   FROM public.settings_versions
  ORDER BY key, version DESC;

CREATE TABLE public.source_domain_service (
    term_key text NOT NULL,
    area_id text NOT NULL,
    editions int8range NOT NULL,
    CONSTRAINT source_domain_service_editions_check CHECK (((NOT isempty(editions)) AND lower_inc(editions) AND (NOT lower_inf(editions))))
);

CREATE TABLE public.tool_config (
    tool text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.topic_week_counts (
    topic_id uuid NOT NULL,
    week date NOT NULL,
    status public.delivery_status NOT NULL,
    calls integer DEFAULT 0 NOT NULL,
    no_item_calls integer DEFAULT 0 NOT NULL,
    CONSTRAINT topic_week_counts_week_check CHECK ((week = (date_trunc('week'::text, (week)::timestamp with time zone))::date))
);

CREATE TABLE public.topics (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    key text NOT NULL,
    area_id text,
    metric_keys text[] NOT NULL,
    value_keys text[] NOT NULL,
    month date NOT NULL,
    dimension_keys text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT topics_id_check CHECK ((uuid_extract_version(id) = 4)),
    CONSTRAINT topics_month_check CHECK ((month = (date_trunc('month'::text, (month)::timestamp with time zone))::date))
);

CREATE VIEW public.v_gap_totals AS
 SELECT t.area_id,
    g.type,
    g.status,
    (count(*))::integer AS gaps
   FROM (public.gaps g
     JOIN public.topics t ON ((t.id = g.topic_id)))
  GROUP BY t.area_id, g.type, g.status;

CREATE VIEW public.v_items_current AS
 SELECT DISTINCT ON (item_id) item_id,
    version_id,
    editions,
    (editions @> ( SELECT live_edition.seq
           FROM public.live_edition)) AS in_live
   FROM public.item_version_service s
  ORDER BY item_id, (lower(editions)) DESC;

CREATE VIEW public.v_item_current_all AS
 SELECT i.id,
    i.kind,
    c.version_id,
    v.version_no,
        CASE
            WHEN c.in_live THEN 'accepted'::text
            ELSE 'retired'::text
        END AS status,
    v.area_id,
    v.title,
    v.summary,
    v.valid_from,
    v.valid_until,
    v.validity,
    v.review_date,
    v.risk,
    v.claim,
    v.audience_groups,
    v.owner_id,
    v.proposer_id,
    v.created_via,
    v.body,
    i.created_at,
    e.created_at AS updated_at,
    v.search,
    v.summary_markup,
    v.body_markup,
    v.not_to_conclude
   FROM (((public.v_items_current c
     JOIN public.items i ON ((i.id = c.item_id)))
     JOIN public.item_versions v ON ((v.id = c.version_id)))
     JOIN public.editions e ON ((e.seq = lower(c.editions))));

CREATE VIEW public.v_overlay_active AS
 SELECT DISTINCT ON (kind_group, scope, COALESCE(area_id, ''::text), COALESCE(item_id, ''::text), COALESCE((flag)::text, ''::text)) seq,
    at,
    kind,
    scope,
    area_id,
    item_id,
    flag,
    reason
   FROM ( SELECT overlay_events.seq,
            overlay_events.at,
            overlay_events.kind,
            overlay_events.scope,
            overlay_events.area_id,
            overlay_events.item_id,
            overlay_events.flag,
            overlay_events.reason,
            overlay_events.actor_id,
            overlay_events.snapshot_id,
                CASE
                    WHEN (overlay_events.kind = ANY (ARRAY['flag_on'::text, 'flag_off'::text])) THEN 'flag'::text
                    ELSE 'stop'::text
                END AS kind_group
           FROM public.overlay_events) e
  ORDER BY kind_group, scope, COALESCE(area_id, ''::text), COALESCE(item_id, ''::text), COALESCE((flag)::text, ''::text), seq DESC;

CREATE VIEW public.v_overlay_on AS
 SELECT seq,
    at,
    kind,
    scope,
    area_id,
    item_id,
    flag,
    reason
   FROM public.v_overlay_active
  WHERE (kind = ANY (ARRAY['flag_on'::text, 'stop_on'::text]));

CREATE VIEW public.v_item_doc AS
 SELECT l.id,
    l.status,
    l.area_id,
    l.kind,
    l.updated_at,
    l.title,
    (jsonb_strip_nulls(jsonb_build_object('body', l.body, 'summaryMarkup', l.summary_markup, 'bodyMarkup', l.body_markup)) || jsonb_build_object('id', l.id, 'kind', l.kind, 'areaId', l.area_id, 'status', l.status, 'version', l.version_no, 'title', l.title, 'summary', l.summary, 'references', COALESCE(( SELECT jsonb_agg(r.definition_ref ORDER BY r.definition_ref) AS jsonb_agg
           FROM public.item_version_refs r
          WHERE (r.version_id = l.version_id)), '[]'::jsonb), 'scope', jsonb_build_object('metrics', COALESCE(( SELECT jsonb_agg(substr(m.metric_key, 8) ORDER BY m.metric_key) AS jsonb_agg
           FROM public.item_version_metrics m
          WHERE (m.version_id = l.version_id)), '[]'::jsonb), 'dimensions', COALESCE(( SELECT jsonb_agg(substr(d.dimension_key, 5) ORDER BY d.dimension_key) AS jsonb_agg
           FROM public.item_version_dimensions d
          WHERE (d.version_id = l.version_id)), '[]'::jsonb), 'dimensionValues', COALESCE(( SELECT jsonb_agg(jsonb_build_object('dimension', substr(d.dimension_key, 5), 'value', split_part(d.value_key, '/'::text, 2)) ORDER BY d.value_key) AS jsonb_agg
           FROM public.item_version_dimension_values d
          WHERE (d.version_id = l.version_id)), '[]'::jsonb)), 'validity', jsonb_build_object('start', l.valid_from, 'end', l.valid_until), 'reviewDate', l.review_date, 'reviewQuestion',
        CASE
            WHEN (((l.kind)::text = 'issue'::text) AND (l.valid_until IS NULL)) THEN 'still_going_on'::text
            ELSE 'still_correct'::text
        END, 'evidence', COALESCE(( SELECT jsonb_agg(jsonb_build_object('url', ev.url, 'quote', ev.quote, 'date', ev.read_on) ORDER BY ev."position") AS jsonb_agg
           FROM public.item_version_evidence ev
          WHERE (ev.version_id = l.version_id)), '[]'::jsonb), 'claimLevel', l.claim, 'riskLevel', l.risk, 'notToConclude', l.not_to_conclude, 'checkFlag', f.flag, 'audience',
        CASE
            WHEN (l.audience_groups IS NULL) THEN jsonb_build_object('kind', 'everyone')
            ELSE jsonb_build_object('kind', 'groups', 'groups', to_jsonb(l.audience_groups))
        END, 'changeMarks', COALESCE(( SELECT jsonb_object_agg(r.definition_ref, r.change_mark) AS jsonb_object_agg
           FROM public.item_version_refs r
          WHERE (r.version_id = l.version_id)), '{}'::jsonb), 'ownerId', l.owner_id, 'proposerId', l.proposer_id, 'createdVia', l.created_via, 'createdAt', to_char((l.created_at AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'::text), 'updatedAt', to_char((l.updated_at AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'::text))) AS doc,
    l.version_id,
    l.summary,
    l.valid_from,
    l.audience_groups
   FROM (public.v_item_current_all l
     LEFT JOIN ( SELECT DISTINCT ON (o.item_id) o.item_id,
            o.flag
           FROM public.v_overlay_on o
          WHERE ((o.kind = 'flag_on'::text) AND (o.item_id IS NOT NULL))
          ORDER BY o.item_id, (o.flag = 'source_missing'::public.source_flag) DESC) f ON ((f.item_id = l.id)));

CREATE VIEW public.v_item_api AS
 SELECT id,
    status,
    area_id,
    kind,
    updated_at,
    title,
    doc,
    version_id,
    summary,
    valid_from,
    audience_groups
   FROM public.v_item_doc d
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.item_bin b
          WHERE ((b.item_id = d.id) AND (b.restored_at IS NULL)))));

CREATE VIEW public.v_item_list AS
 SELECT id,
    kind,
    version_id,
    version_no,
    status,
    area_id,
    title,
    summary,
    valid_from,
    valid_until,
    validity,
    review_date,
    risk,
    claim,
    audience_groups,
    owner_id,
    proposer_id,
    created_via,
    body,
    created_at,
    updated_at,
    search,
    summary_markup,
    body_markup,
    not_to_conclude
   FROM public.v_item_current_all l
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.item_bin b
          WHERE ((b.item_id = l.id) AND (b.restored_at IS NULL)))));

CREATE VIEW public.v_item_index AS
 SELECT l.id,
    l.audience_groups,
    jsonb_build_object('id', l.id, 'kind', l.kind, 'areaId', l.area_id, 'status', l.status, 'version', l.version_no, 'title', l.title, 'summary', l.summary, 'scope', jsonb_build_object('metrics', COALESCE(( SELECT jsonb_agg(substr(m.metric_key, 8) ORDER BY m.metric_key) AS jsonb_agg
           FROM public.item_version_metrics m
          WHERE (m.version_id = l.version_id)), '[]'::jsonb), 'dimensions', COALESCE(( SELECT jsonb_agg(substr(d.dimension_key, 5) ORDER BY d.dimension_key) AS jsonb_agg
           FROM public.item_version_dimensions d
          WHERE (d.version_id = l.version_id)), '[]'::jsonb), 'dimensionValues', COALESCE(( SELECT jsonb_agg(jsonb_build_object('dimension', substr(d.dimension_key, 5), 'value', split_part(d.value_key, '/'::text, 2)) ORDER BY d.value_key) AS jsonb_agg
           FROM public.item_version_dimension_values d
          WHERE (d.version_id = l.version_id)), '[]'::jsonb)), 'validity', jsonb_build_object('start', l.valid_from, 'end', l.valid_until), 'reviewDate', l.review_date, 'reviewQuestion',
        CASE
            WHEN (((l.kind)::text = 'issue'::text) AND (l.valid_until IS NULL)) THEN 'still_going_on'::text
            ELSE 'still_correct'::text
        END, 'checkFlag', f.flag, 'ownerId', l.owner_id, 'proposerId', l.proposer_id, 'updatedAt', to_char((l.updated_at AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'::text)) AS entry
   FROM (public.v_item_list l
     LEFT JOIN ( SELECT DISTINCT ON (o.item_id) o.item_id,
            o.flag
           FROM public.v_overlay_on o
          WHERE ((o.kind = 'flag_on'::text) AND (o.item_id IS NOT NULL))
          ORDER BY o.item_id, (o.flag = 'source_missing'::public.source_flag) DESC) f ON ((f.item_id = l.id)));

CREATE TABLE public.vocab_term_refs (
    version_id uuid NOT NULL,
    definition_ref text NOT NULL,
    CONSTRAINT vocab_term_refs_definition_ref_check CHECK ((btrim(definition_ref) <> ''::text))
);

CREATE TABLE public.vocab_term_service (
    term_key text NOT NULL,
    version_id uuid NOT NULL,
    editions int8range NOT NULL,
    CONSTRAINT vocab_term_service_editions_check CHECK (((NOT isempty(editions)) AND lower_inc(editions) AND (NOT lower_inf(editions))))
);

CREATE TABLE public.vocab_terms (
    key text NOT NULL,
    kind public.term_kind NOT NULL,
    parent_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vocab_terms_check CHECK ((((kind = 'metric_group'::public.term_kind) AND (key ~ '^group:[a-z0-9_]+$'::text) AND (parent_key IS NULL)) OR ((kind = 'metric'::public.term_kind) AND (key ~ '^metric:[a-z0-9_]+$'::text)) OR ((kind = 'dimension'::public.term_kind) AND (key ~ '^dim:[a-z0-9_]+$'::text) AND (parent_key IS NULL)) OR ((kind = 'dimension_value'::public.term_kind) AND (key ~ '^val:[a-z0-9_]+/[a-z0-9_]+$'::text) AND (parent_key IS NOT NULL))))
);

CREATE VIEW public.v_mention_status WITH (security_invoker='true') AS
 SELECT m.version_id,
    m.field,
    m."position",
    m.label,
    COALESCE(m.term_key, ('item:'::text || m.item_id), ('area:'::text || m.area_id)) AS target,
        CASE
            WHEN (m.item_id IS NOT NULL) THEN 'item'::text
            WHEN (m.area_id IS NOT NULL) THEN 'area'::text
            ELSE ( SELECT (k.kind)::text AS kind
               FROM public.vocab_terms k
              WHERE (k.key = m.term_key))
        END AS target_type,
    d.ref AS definition_ref,
    d.renamed_to,
    rep.item_id AS replaced_by,
        CASE
            WHEN (m.item_id IS NOT NULL) THEN
            CASE
                WHEN (EXISTS ( SELECT 1
                   FROM public.item_version_service s
                  WHERE ((s.item_id = m.item_id) AND (s.editions @> ( SELECT live_edition.seq
                           FROM public.live_edition))))) THEN 'current'::text
                WHEN (rep.item_id IS NOT NULL) THEN 'replaced'::text
                ELSE 'retired'::text
            END
            WHEN (m.area_id IS NOT NULL) THEN 'current'::text
            WHEN (t.served IS NULL) THEN 'unresolved'::text
            WHEN (d.ref IS NULL) THEN 'current'::text
            WHEN d.missing THEN 'source_missing'::text
            WHEN d.changed THEN 'source_changed'::text
            ELSE 'current'::text
        END AS status
   FROM (((public.item_version_mentions m
     LEFT JOIN LATERAL ( SELECT true AS served,
            public.cl_relevant_refs(COALESCE(( SELECT array_agg(r.definition_ref ORDER BY (r.definition_ref COLLATE "C")) AS array_agg
                   FROM public.vocab_term_refs r
                  WHERE (r.version_id = s.version_id)), '{}'::text[]), public.cl_version_metric_refs(m.version_id)) AS refs
           FROM public.vocab_term_service s
          WHERE ((s.term_key = m.term_key) AND (s.editions @> ( SELECT live_edition.seq
                   FROM public.live_edition)))) t ON ((m.term_key IS NOT NULL)))
     LEFT JOIN LATERAL ( SELECT d_1.ref,
            d_1.renamed_to,
            (d_1.missing_since_snapshot IS NOT NULL) AS missing,
            COALESCE(((m.definition_ref = d_1.ref) AND (m.change_mark <> d_1.change_mark)), false) AS changed
           FROM (unnest(t.refs) WITH ORDINALITY x(ref, n)
             JOIN public.definitions d_1 ON ((d_1.ref = x.ref)))
          ORDER BY (d_1.missing_since_snapshot IS NOT NULL) DESC, COALESCE(((m.definition_ref = d_1.ref) AND (m.change_mark <> d_1.change_mark)), false) DESC, x.n
         LIMIT 1) d ON (true))
     LEFT JOIN LATERAL ( SELECT s.item_id
           FROM (public.item_version_service s
             JOIN public.item_version_replaces r ON ((r.version_id = s.version_id)))
          WHERE ((r.replaced_item_id = m.item_id) AND (s.editions @> ( SELECT live_edition.seq
                   FROM public.live_edition)))
          ORDER BY s.item_id
         LIMIT 1) rep ON ((m.item_id IS NOT NULL)));

CREATE VIEW public.v_stale_links WITH (security_invoker='true') AS
 SELECT s.item_id,
    v.area_id,
    v.title,
    ms.version_id,
    ms.field,
    ms."position",
    ms.label,
    ms.target,
    ms.target_type,
    ms.definition_ref,
    ms.renamed_to,
    ms.replaced_by,
    ms.status
   FROM ((public.item_version_service s
     JOIN public.item_versions v ON ((v.id = s.version_id)))
     JOIN public.v_mention_status ms ON ((ms.version_id = s.version_id)))
  WHERE ((s.editions @> ( SELECT live_edition.seq
           FROM public.live_edition)) AND (ms.status <> 'current'::text));

CREATE VIEW public.v_topic_weeks AS
 SELECT c.topic_id,
    c.week,
    c.calls,
    c.no_item_calls,
    (c.calls >= m.minimum) AS shown,
        CASE
            WHEN ((c.no_item_calls = 0) OR (c.no_item_calls >= m.minimum)) THEN c.no_item_calls
            ELSE NULL::integer
        END AS shown_no_item_calls
   FROM (( SELECT topic_week_counts.topic_id,
            topic_week_counts.week,
            (sum(topic_week_counts.calls))::integer AS calls,
            (sum(topic_week_counts.no_item_calls))::integer AS no_item_calls
           FROM public.topic_week_counts
          GROUP BY topic_week_counts.topic_id, topic_week_counts.week) c
     CROSS JOIN ( SELECT ((settings_current.value #>> '{}'::text[]))::integer AS minimum
           FROM public.settings_current
          WHERE (settings_current.key = 'privacy.min_count'::text)) m);

CREATE VIEW public.v_topic_counts_public WITH (security_barrier='true') AS
 SELECT t.area_id,
    t.metric_keys,
    t.value_keys,
    t.month,
    c.week,
    c.calls,
    c.shown_no_item_calls AS no_item_calls,
    t.dimension_keys
   FROM (public.v_topic_weeks c
     JOIN public.topics t ON ((t.id = c.topic_id)))
  WHERE c.shown;

CREATE VIEW public.v_version_links WITH (security_invoker='true') AS
 SELECT item_version_mentions.version_id,
    'mentions'::text AS rel,
        CASE
            WHEN (item_version_mentions.term_key IS NOT NULL) THEN ( SELECT (t.kind)::text AS kind
               FROM public.vocab_terms t
              WHERE (t.key = item_version_mentions.term_key))
            WHEN (item_version_mentions.item_id IS NOT NULL) THEN 'item'::text
            ELSE 'area'::text
        END AS to_kind,
    COALESCE(item_version_mentions.term_key, item_version_mentions.item_id, item_version_mentions.area_id) AS to_id,
    item_version_mentions.label,
    item_version_mentions.definition_ref,
    item_version_mentions.change_mark
   FROM public.item_version_mentions
UNION ALL
 SELECT item_version_metrics.version_id,
    'applies_to'::text AS rel,
    'metric'::text AS to_kind,
    item_version_metrics.metric_key AS to_id,
    NULL::text AS label,
    NULL::text AS definition_ref,
    NULL::text AS change_mark
   FROM public.item_version_metrics
UNION ALL
 SELECT item_version_dimension_values.version_id,
    'applies_to'::text AS rel,
    'dimension_value'::text AS to_kind,
    item_version_dimension_values.value_key AS to_id,
    NULL::text AS label,
    NULL::text AS definition_ref,
    NULL::text AS change_mark
   FROM public.item_version_dimension_values
UNION ALL
 SELECT item_version_replaces.version_id,
    'replaces'::text AS rel,
    'item'::text AS to_kind,
    item_version_replaces.replaced_item_id AS to_id,
    NULL::text AS label,
    NULL::text AS definition_ref,
    NULL::text AS change_mark
   FROM public.item_version_replaces
UNION ALL
 SELECT item_version_conflicts.version_id,
    'conflicts_with'::text AS rel,
    'item'::text AS to_kind,
    item_version_conflicts.other_item_id AS to_id,
    NULL::text AS label,
    NULL::text AS definition_ref,
    NULL::text AS change_mark
   FROM public.item_version_conflicts
UNION ALL
 SELECT item_version_dimensions.version_id,
    'applies_to'::text AS rel,
    'dimension'::text AS to_kind,
    item_version_dimensions.dimension_key AS to_id,
    NULL::text AS label,
    NULL::text AS definition_ref,
    NULL::text AS change_mark
   FROM public.item_version_dimensions;

CREATE TABLE public.vocab_term_versions (
    id uuid DEFAULT uuidv7() NOT NULL,
    term_key text NOT NULL,
    version_no integer NOT NULL,
    name text NOT NULL,
    aliases text[] DEFAULT '{}'::text[] NOT NULL,
    area_id text,
    proposer_id uuid,
    content_digest bytea NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vocab_term_versions_content_digest_check CHECK ((length(content_digest) = 32)),
    CONSTRAINT vocab_term_versions_name_check CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT vocab_term_versions_version_no_check CHECK ((version_no >= 1))
);

CREATE TABLE public.webhook_deliveries (
    id uuid DEFAULT uuidv7() NOT NULL,
    endpoint_id uuid NOT NULL,
    event_seq bigint NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    http_status integer,
    last_error text,
    next_attempt_at timestamp with time zone DEFAULT now(),
    delivered_at timestamp with time zone,
    CONSTRAINT webhook_deliveries_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'delivered'::text, 'failed'::text, 'gave_up'::text])))
);

CREATE TABLE public.webhook_endpoints (
    id uuid DEFAULT uuidv7() NOT NULL,
    name text NOT NULL,
    url text NOT NULL,
    secret_ref text NOT NULL,
    events text[] NOT NULL,
    area_id text,
    enabled boolean DEFAULT true NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT webhook_endpoints_url_check CHECK ((url ~ '^https://'::text))
);

REVOKE ALL ON FUNCTION auth.bootstrap_person(p_email text, p_name text, p_roles public.global_role[]) FROM PUBLIC;

